1	[CmdletBinding()]
2	param(
3	  [ValidateSet('Initialize', 'Tick', 'Transition', 'ObserveRetry', 'RegisterSynthetic', 'ReplayVerify', 'RebuildSnapshot', 'TickPreflight')]
4	  [string]$Mode = 'Tick',
5	
6	  [string]$Workspace = '',
7	  [string]$ControlWorktree = '',
8	  [string]$GitCommand = 'git',
9	  [string]$NodeCommand = 'node',
10	  [string]$MutexName = 'Global\aal-agent-claims',
11	  [string]$OwnerSession = '',
12	  [int]$LeaseMinutes = 360,
13	  [string]$EffectKey = '',
14	  [string]$ToStatus = '',
15	  [Nullable[int]]$ExpectedAttemptId,
16	  [Nullable[int]]$ExpectedSequence,
17	  [string]$ExpectedStatus,
18	  [string]$PackageClass = 'wire',
19	  [string]$CompletionEvidencePath = '',
20	  [string]$ObserveResultPath = '',
21	  [string[]]$SyntheticLeaves = @(),
22	  [switch]$TestMode,
23	  [switch]$SkipMutex,
24	  [switch]$NoPush
25	)
26	
27	$ErrorActionPreference = 'Stop'
28	. (Join-Path $PSScriptRoot 'wire-or-cut-dispatch-core.ps1')
29	$script:WireCutDispatchInvocationParameters = $PSBoundParameters
30	
31	function Stop-WireCutDispatch {
32	  param(
33	    [Parameter(Mandatory)][string]$Code,
34	    [Parameter(Mandatory)][string]$Message
35	  )
36	  Write-Output "[$Code] $Message"
37	  exit 1
38	}
39	
40	function Emit-WireCutDispatchSuccess {
41	  param([string]$Message)
42	  Write-Output "[WOC-D000] $Message"
43	  exit 0
44	}
45	
46	$script:WireCutDispatchTestMode = $false
47	if ($TestMode) {
48	  if ($env:WIRE_OR_CUT_DISPATCHER_TEST -ne '1') {
49	    Stop-WireCutDispatch 'WOC-D099' 'TestMode requires WIRE_OR_CUT_DISPATCHER_TEST=1.'
50	  }
51	  $script:WireCutDispatchTestMode = $true
52	} else {
53	  if ($GitCommand -ne 'git' -or $NodeCommand -ne 'node' -or $MutexName -ne 'Global\aal-agent-claims') {
54	    Stop-WireCutDispatch 'WOC-D099' 'Production git/node/mutex overrides are not permitted outside TestMode.'
55	  }
56	}
57	if (($SkipMutex -or $NoPush) -and -not $script:WireCutDispatchTestMode) {
58	  Stop-WireCutDispatch 'WOC-D099' 'SkipMutex and NoPush are test-only dispatcher controls.'
59	}
60	
61	function Assert-WireCutExpectedCas {
62	  param(
63	    [Parameter(Mandatory)]$Entry
64	  )
65	  foreach ($name in @('ExpectedStatus', 'ExpectedAttemptId', 'ExpectedSequence')) {
66	    if (-not $script:WireCutDispatchInvocationParameters.ContainsKey($name)) {
67	      Stop-WireCutDispatch 'WOC-D006' 'Every mutation requires expected status, attempt_id, and transition sequence.'
68	    }
69	  }
70	  if ([string]::IsNullOrWhiteSpace($ExpectedStatus) -or
71	      $null -eq $ExpectedAttemptId -or [int]$ExpectedAttemptId -lt 1 -or
72	      $null -eq $ExpectedSequence -or [int]$ExpectedSequence -lt 0) {
73	    Stop-WireCutDispatch 'WOC-D006' 'CAS expectation fields are invalid.'
74	  }
75	  if ([string]$Entry.status -ne $ExpectedStatus) {
76	    Stop-WireCutDispatch 'WOC-D006' 'CAS status mismatch.'
77	  }
78	  if ([int]$Entry.attempt_id -ne [int]$ExpectedAttemptId) {
79	    Stop-WireCutDispatch 'WOC-D006' 'CAS attempt_id mismatch.'
80	  }
81	  if ([int]$Entry.last_transition_sequence -ne [int]$ExpectedSequence) {
82	    Stop-WireCutDispatch 'WOC-D006' 'CAS sequence mismatch.'
83	  }
84	}
85	
86	function Assert-WireCutExpectedAbsentCas {
87	  foreach ($name in @('ExpectedStatus', 'ExpectedAttemptId', 'ExpectedSequence')) {
88	    if (-not $script:WireCutDispatchInvocationParameters.ContainsKey($name)) {
89	      Stop-WireCutDispatch 'WOC-D006' 'Synthetic registration requires an explicit absent-entry CAS tuple.'
90	    }
91	  }
92	  if ($ExpectedStatus -ne '__absent__' -or [int]$ExpectedAttemptId -ne 0 -or [int]$ExpectedSequence -ne 0) {
93	    Stop-WireCutDispatch 'WOC-D006' 'Synthetic registration CAS tuple must be __absent__,0,0.'
94	  }
95	}
96	
97	if ([string]::IsNullOrWhiteSpace($Workspace)) {
98	  Stop-WireCutDispatch 'WOC-D001' 'Workspace is required.'
99	}
100	$resolvedWorkspace = Resolve-WireCutExactPath $Workspace
101	if (-not $resolvedWorkspace) {
102	  Stop-WireCutDispatch 'WOC-D001' 'Workspace path cannot be resolved.'
103	}
104	$top = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
105	  'rev-parse', '--show-toplevel'
106	)
107	$resolvedTop = if ($top.ExitCode -eq 0) { Resolve-WireCutExactPath $top.Output } else { $null }
108	if ($top.ExitCode -ne 0 -or -not $resolvedTop -or
109	    -not $resolvedTop.Equals($resolvedWorkspace, [StringComparison]::OrdinalIgnoreCase)) {
110	  Stop-WireCutDispatch 'WOC-D001' 'Workspace is not the exact root of a git worktree.'
111	}
112	
113	$mutex = $null
114	$mutexHeld = $false
115	if (-not $SkipMutex) {
116	  $mutex = [System.Threading.Mutex]::new($false, $MutexName)
117	  try {
118	    try { $mutexHeld = $mutex.WaitOne(0) }
119	    catch [System.Threading.AbandonedMutexException] { $mutexHeld = $true }
120	    if (-not $mutexHeld) { Stop-WireCutDispatch 'WOC-D001' 'Another dispatcher instance holds the mutex.' }
121	  } catch {
122	    Stop-WireCutDispatch 'WOC-D001' 'Could not acquire dispatcher mutex.'
123	  }
124	}
125	
126	try {
127	  $preflightMode = if ($Mode -eq 'Initialize') { 'Initialize' } else { 'Tick' }
128	  if ($Mode -in @('Initialize')) {
129	    $localState = Test-WireCutLocalInitializationState -GitCommand $GitCommand -Workspace $resolvedWorkspace
130	    if (-not $localState.ok) {
131	      Stop-WireCutDispatch 'WOC-D008' "Initialize is one-shot and local $($localState.reason) state already exists."
132	    }
133	    $status = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
134	      'status', '--porcelain=v1'
135	    )
136	    if ($status.ExitCode -ne 0 -or -not [string]::IsNullOrWhiteSpace($status.Output)) {
137	      Stop-WireCutDispatch 'WOC-D013' 'Workspace is dirty; initialization refuses to proceed.'
138	    }
139	    $initCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Initialize'
140	    if (-not $initCheck.ok) { Stop-WireCutDispatch $initCheck.code $initCheck.message }
141	    $planCommit = $initCheck.origin_main
142	    $registryPath = Join-Path $resolvedWorkspace $script:WireCutDispatchRegistryRelative
143	    $digest = Get-WireCutCanonicalTextSha256 -Path $registryPath
144	    $registry = Get-Content -Raw -LiteralPath $registryPath -Encoding utf8 | ConvertFrom-Json
145	    $packages = [ordered]@{}
146	    foreach ($wp in @($registry.work_packages)) {
147	      if (-not $wp.id) { continue }
148	      $seed = if ($wp.PSObject.Properties['status']) { [string]$wp.status } else { 'pending' }
149	      $packages[$wp.id] = New-WireCutPackageRuntimeEntry -EffectKey $wp.id -SeedStatus $seed
150	    }
151	    $snapshot = [ordered]@{
152	      schema_version = 1
153	      plan_binding = [ordered]@{
154	        plan_commit = $planCommit
155	        registry_sha256 = $digest
156	      }
157	      last_transition_sequence = 0
158	      work_packages = (Sort-WireCutWorkPackages -Packages $packages)
159	    }
160	    $stateDir = Split-Path -Parent (Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative)
161	    if (-not (Test-Path -LiteralPath $stateDir -PathType Container)) {
162	      New-Item -ItemType Directory -Path $stateDir -Force | Out-Null
163	    }
164	    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
165	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
166	    $branch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
167	      'checkout', '-b', $script:WireCutDispatchStateBranch
168	    )
169	    if ($branch.ExitCode -ne 0) { Stop-WireCutDispatch 'WOC-D008' 'Could not create local wirecut-state branch.' }
170	    $initEvent = [ordered]@{
171	      sequence = 0
172	      at = Get-WireCutUtcIsoNow
173	      type = 'sequence_init'
174	      plan_commit = $planCommit
175	      registry_sha256 = $digest
176	    }
177	    Add-WireCutDispatchEventLine -EventsPath $eventsPath -Event $initEvent
178	    Write-WireCutCanonicalJson -Path $snapshotPath -Object $snapshot
179	    $add = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
180	      'add', '--',
181	      ($script:WireCutDispatchStateRelative -replace '\\','/'),
182	      ($script:WireCutDispatchEventsRelative -replace '\\','/')
183	    )
184	    if ($add.ExitCode -ne 0) { Stop-WireCutDispatch 'WOC-D008' 'Could not stage initialization state.' }
185	    $commit = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
186	      'commit', '-m', 'wire-or-cut: initialize campaign state sequence 0'
187	    )
188	    if ($commit.ExitCode -ne 0) { Stop-WireCutDispatch 'WOC-D008' 'Could not commit initialization state.' }
189	  if (-not $NoPush) {
190	      $push = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
191	        'push', '-u', 'origin', "HEAD:refs/heads/$($script:WireCutDispatchStateBranch)"
192	      )
193	      if ($push.ExitCode -ne 0) { Stop-WireCutDispatch 'WOC-D007' 'Initialization push was rejected (non-fast-forward).' }
194	    }
195	    if ([string]::IsNullOrWhiteSpace($ControlWorktree)) {
196	      Stop-WireCutDispatch 'WOC-D014' 'Initialize requires a dedicated clean control worktree for wirecut-state handoff.'
197	    }
198	    $handoff = Invoke-WireCutControlWorktreeHandoff -GitCommand $GitCommand -ControlWorktree $ControlWorktree
199	    if (-not $handoff.ok) { Stop-WireCutDispatch $handoff.code $handoff.message }
200	    Emit-WireCutDispatchSuccess "initialization complete; state_commit=$($handoff.state_commit)"
201	  }
202	
203	  if ($Mode -eq 'TickPreflight') {
204	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
205	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
206	    Emit-WireCutDispatchSuccess "tick preflight coherent; plan_commit=$($tickCheck.plan_commit)"
207	  }
208	
209	  if ($Mode -eq 'Tick') {
210	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
211	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
212	    $expired = @()
213	    foreach ($name in (Get-WireCutWorkPackageProperties -WorkPackages $tickCheck.snapshot.work_packages)) {
214	      $entry = Get-WireCutWorkPackageEntry -WorkPackages $tickCheck.snapshot.work_packages -EffectKey $name
215	      if ($null -ne $entry.lease -and -not (Test-WireCutLeaseLive -Lease $entry.lease)) {
216	        $expired += [string]$entry.effect_key
217	      }
218	    }
219	    [ordered]@{
220	      code = 'WOC-D000'
221	      kind = 'wire-or-cut-tick'
222	      expired_effect_keys = @($expired)
223	      expired_lease_count = @($expired).Count
224	      required_action = 'ObserveRetry'
225	    } | ConvertTo-Json -Compress | Write-Output
226	    exit 0
227	  }
228	
229	  if ($Mode -eq 'RebuildSnapshot') {
230	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
231	    if (-not (Test-Path -LiteralPath $eventsPath -PathType Leaf)) {
232	      Stop-WireCutDispatch 'WOC-D009' 'Event ledger file is missing.'
233	    }
234	    $events = Read-WireCutDispatchEvents -EventsPath $eventsPath
235	    if ($null -eq $events) { Stop-WireCutDispatch 'WOC-D009' 'Event ledger is corrupt.' }
236	    if (@($events).Count -lt 1) {
237	      $raw = [IO.File]::ReadAllText($eventsPath)
238	      Stop-WireCutDispatch 'WOC-D009' "Event ledger is empty (bytes=$($raw.Length))."
239	    }
240	    $init = $events | Where-Object { [string]$_.type -eq 'sequence_init' } | Select-Object -First 1
241	    if ($null -eq $init) { Stop-WireCutDispatch 'WOC-D009' 'Initialization event is missing.' }
242	    $planCommit = [string]$init.plan_commit
243	    $registry = Read-WireCutDispatchRegistryAtCommit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Commit $planCommit
244	    if ($null -eq $registry) { Stop-WireCutDispatch 'WOC-D004' 'Bound plan registry cannot be read for rebuild.' }
245	    $binding = [ordered]@{
246	      plan_commit = $planCommit
247	      registry_sha256 = [string]$init.registry_sha256
248	    }
249	    $rebuilt = Invoke-WireCutReplayEvents -Registry $registry -PlanBinding $binding -Events $events
250	    if ($null -eq $rebuilt) { Stop-WireCutDispatch 'WOC-D009' 'Replay rebuild failed.' }
251	    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
252	    Write-WireCutCanonicalJson -Path $snapshotPath -Object $rebuilt
253	    Emit-WireCutDispatchSuccess 'rebuild snapshot from events complete'
254	  }
255	
256	  if ($Mode -eq 'ReplayVerify') {
257	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
258	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
259	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
260	    $events = Read-WireCutDispatchEvents -EventsPath $eventsPath
261	    $rebuilt = Invoke-WireCutReplayEvents -Registry $tickCheck.registry -PlanBinding $tickCheck.snapshot.plan_binding -Events $events
262	    if ($null -eq $rebuilt) { Stop-WireCutDispatch 'WOC-D009' 'Replay rebuild failed.' }
263	    $left = Get-WireCutCanonicalJsonSha256 -Object (Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot)
264	    $right = Get-WireCutCanonicalJsonSha256 -Object $rebuilt
265	    if ($left -ne $right) { Stop-WireCutDispatch 'WOC-D009' 'Replay digest does not match snapshot.' }
266	    Emit-WireCutDispatchSuccess 'replay verify passed'
267	  }
268	
269	  if ($Mode -eq 'RegisterSynthetic') {
270	    if (-not $TestMode) { Stop-WireCutDispatch 'WOC-D099' 'RegisterSynthetic is test-only.' }
271	    if ($SyntheticLeaves.Count -lt 1) { Stop-WireCutDispatch 'WOC-D011' 'SyntheticLeaves is required.' }
272	    Assert-WireCutExpectedAbsentCas
273	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
274	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
275	    $snapshot = Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot
276	    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
277	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
278	    $events = @()
279	    foreach ($leaf in @($SyntheticLeaves)) {
280	      if (Test-WireCutWorkPackageExists -WorkPackages $snapshot.work_packages -EffectKey $leaf) { continue }
281	      Set-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $leaf -Entry (New-WireCutPackageRuntimeEntry -EffectKey $leaf -SeedStatus 'pending')
282	      $entry = Get-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $leaf
283	      $entry | Add-Member -NotePropertyName 'class' -NotePropertyValue $PackageClass -Force
284	      $events += [ordered]@{
285	        type = 'synthetic_register'
286	        effect_key = $leaf
287	        class = $PackageClass
288	      }
289	    }
290	    if ($events.Count -lt 1) { Stop-WireCutDispatch 'WOC-D011' 'Synthetic leaf already exists.' }
291	    $write = Invoke-WireCutDispatchStateWrite -GitCommand $GitCommand -Workspace $resolvedWorkspace `
292	      -SnapshotPath $snapshotPath -EventsPath $eventsPath -SnapshotObject $snapshot -EventObjects $events `
293	      -CommitMessage 'wire-or-cut: register synthetic leaves'
294	    if (-not $write.ok) {
295	      if ($write.reason -eq 'push_rejected_non_ff') { Stop-WireCutDispatch 'WOC-D007' 'Synthetic register push rejected (non-fast-forward).' }
296	      Stop-WireCutDispatch 'WOC-D006' "Synthetic register failed: $($write.reason)"
297	    }
298	    Emit-WireCutDispatchSuccess ("synthetic leaves registered: " + ($SyntheticLeaves -join ','))
299	  }
300	
301	  if ($Mode -eq 'Transition') {
302	    if ([string]::IsNullOrWhiteSpace($EffectKey) -or [string]::IsNullOrWhiteSpace($ToStatus)) {
303	      Stop-WireCutDispatch 'WOC-D011' 'Transition requires EffectKey and ToStatus.'
304	    }
305	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
306	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
307	    $snapshot = Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot
308	    if (-not (Test-WireCutWorkPackageExists -WorkPackages $snapshot.work_packages -EffectKey $EffectKey)) {
309	      Stop-WireCutDispatch 'WOC-D011' "Unknown effect_key $EffectKey."
310	    }
311	    $entry = Get-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $EffectKey
312	    Assert-WireCutExpectedCas -Entry $entry
313	    if ($null -ne $entry.lease -and (Test-WireCutLeaseLive -Lease $entry.lease) -and $ToStatus -eq 'leased') {
314	      Stop-WireCutDispatch 'WOC-D012' 'Live unexpired lease blocks redispatch.'
315	    }
316	    # Registry waivers[] are an operator governance mechanism; this dispatcher
317	    # has no waiver mutation verb, so it never manufactures a waived status.
318	    $valid = @('pending', 'leased', 'dispatched', 'reviewing', 'blocked', 'done')
319	    if ($valid -notcontains $ToStatus) { Stop-WireCutDispatch 'WOC-D011' "Invalid target status $ToStatus." }
320	    $fromStatus = [string]$entry.status
321	    $allowed = @{
322	      pending = @('leased')
323	      leased = @('dispatched')
324	      dispatched = @('reviewing')
325	      reviewing = @('done', 'blocked')
326	    }
327	    if (-not $allowed.ContainsKey($fromStatus) -or $allowed[$fromStatus] -notcontains $ToStatus) {
328	      Stop-WireCutDispatch 'WOC-D011' "Transition $fromStatus -> $ToStatus is not allowed."
329	    }
330	    $event = [ordered]@{
331	      type = 'status_transition'
332	      effect_key = $EffectKey
333	      from_status = $fromStatus
334	      to_status = $ToStatus
335	      attempt_id = [int]$entry.attempt_id
336	    }
337	    $entry.status = $ToStatus
338	    if ($ToStatus -eq 'leased') {
339	      if ([string]::IsNullOrWhiteSpace($OwnerSession)) {
340	        Stop-WireCutDispatch 'WOC-D011' 'Lease transition requires OwnerSession.'
341	      }
342	      $expires = [DateTime]::UtcNow.AddMinutes($LeaseMinutes).ToString('o')
343	      if ($TestMode -and $LeaseMinutes -lt 0) {
344	        $expires = [DateTime]::UtcNow.AddMinutes($LeaseMinutes).ToString('o')
345	      }
346	      $lease = [ordered]@{
347	        owner_session = $OwnerSession
348	        attempt_id = [int]$entry.attempt_id
349	        expires_at = $expires
350	        effect_key = $EffectKey
351	      }
352	      $entry.lease = $lease
353	      $event.lease = $lease
354	    } elseif ($ToStatus -in @('dispatched', 'reviewing', 'done', 'blocked')) {
355	      if ($null -ne $entry.lease) { $event.clear_lease = $true }
356	      $entry.lease = $null
357	    }
358	    if ($ToStatus -eq 'done') {
359	      $class = $PackageClass
360	      if ($entry.PSObject.Properties['class']) { $class = [string]$entry.class }
361	      if ([string]::IsNullOrWhiteSpace($CompletionEvidencePath) -or -not (Test-Path -LiteralPath $CompletionEvidencePath -PathType Leaf)) {
362	        Stop-WireCutDispatch 'WOC-D011' 'Done transition requires CompletionEvidencePath.'
363	      }
364	      $evidence = Get-Content -Raw -LiteralPath $CompletionEvidencePath -Encoding utf8 | ConvertFrom-Json
365	      if (-not (Test-WireCutCompletionEvidence -Registry $tickCheck.registry -Class $class -Evidence $evidence -PackageId $EffectKey)) {
366	        Stop-WireCutDispatch 'WOC-D011' 'Completion evidence does not satisfy the class-typed contract.'
367	      }
368	      $entry.completion_evidence_refs = $evidence
369	      $event.completion_evidence_refs = $evidence
370	    }
371	    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
372	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
373	    if ($NoPush) {
374	      $mutation = Write-WireCutDispatchStateMutation -SnapshotPath $snapshotPath -EventsPath $eventsPath `
375	        -SnapshotObject $snapshot -EventObjects @($event)
376	      Emit-WireCutDispatchSuccess "transition staged locally $fromStatus->$ToStatus effect_key=$EffectKey sequence=$($mutation.sequence)"
377	    } else {
378	      $write = Invoke-WireCutDispatchStateWrite -GitCommand $GitCommand -Workspace $resolvedWorkspace `
379	        -SnapshotPath $snapshotPath -EventsPath $eventsPath -SnapshotObject $snapshot -EventObjects @($event) `
380	        -CommitMessage "wire-or-cut: $EffectKey $fromStatus->$ToStatus"
381	      if (-not $write.ok) {
382	        if ($write.reason -eq 'push_rejected_non_ff') { Stop-WireCutDispatch 'WOC-D007' 'Transition push rejected (non-fast-forward); re-read required.' }
383	        Stop-WireCutDispatch 'WOC-D006' "Transition write failed: $($write.reason)"
384	      }
385	      Emit-WireCutDispatchSuccess "transition $fromStatus->$ToStatus effect_key=$EffectKey sequence=$($write.sequence)"
386	    }
387	  }
388	
389	  if ($Mode -eq 'ObserveRetry') {
390	    if ([string]::IsNullOrWhiteSpace($EffectKey)) { Stop-WireCutDispatch 'WOC-D011' 'ObserveRetry requires EffectKey.' }
391	    if ([string]::IsNullOrWhiteSpace($ObserveResultPath) -or -not (Test-Path -LiteralPath $ObserveResultPath -PathType Leaf)) {
392	      Stop-WireCutDispatch 'WOC-D013' 'ObserveRetry requires ObserveResultPath.'
393	    }
394	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
395	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
396	    $snapshot = Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot
397	    if (-not (Test-WireCutWorkPackageExists -WorkPackages $snapshot.work_packages -EffectKey $EffectKey)) {
398	      Stop-WireCutDispatch 'WOC-D011' "Unknown effect_key $EffectKey."
399	    }
400	    $entry = Get-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $EffectKey
401	    Assert-WireCutExpectedCas -Entry $entry
402	    $liveLease = $null -ne $entry.lease -and (Test-WireCutLeaseLive -Lease $entry.lease)
403	    if ($liveLease) {
404	      Stop-WireCutDispatch 'WOC-D012' 'Live unexpired lease blocks observe-before-retry.'
405	    }
406	    $expiredLease = $null -ne $entry.lease
407	    if ([string]$entry.status -ne 'blocked' -and -not $expiredLease) {
408	      Stop-WireCutDispatch 'WOC-D013' 'ObserveRetry requires a blocked package or an expired lease.'
409	    }
410	    $observe = Get-Content -Raw -LiteralPath $ObserveResultPath -Encoding utf8 | ConvertFrom-Json
411	    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
412	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
413	    $oldAttempt = [int]$entry.attempt_id
414	    $newAttempt = $oldAttempt + 1
415	    $entry.status = 'blocked'
416	    $entry.lease = $null
417	    $tombstone = [ordered]@{
418	      type = 'attempt_tombstone'
419	      effect_key = $EffectKey
420	      attempt_id = $oldAttempt
421	      reason = if ($expiredLease) { 'lease_expired' } else { 'blocked_observe_retry' }
422	    }
423	    $reconciledStatus = 'pending'
424	    if ($observe.PSObject.Properties['external_done'] -and [bool]$observe.external_done) {
425	      $reconciledStatus = 'reviewing'
426	    }
427	    $reconcile = [ordered]@{
428	      type = 'observe_reconcile'
429	      effect_key = $EffectKey
430	      to_status = $reconciledStatus
431	      new_attempt_id = $newAttempt
432	      observed = $observe
433	    }
434	    $entry.status = $reconciledStatus
435	    $entry.attempt_id = $newAttempt
436	    $entry.lease = $null
437	    $write = Invoke-WireCutDispatchStateWrite -GitCommand $GitCommand -Workspace $resolvedWorkspace `
438	      -SnapshotPath $snapshotPath -EventsPath $eventsPath -SnapshotObject $snapshot -EventObjects @($tombstone, $reconcile) `
439	      -CommitMessage "wire-or-cut: observe-reconcile $EffectKey -> $reconciledStatus fence=$newAttempt"
440	    if (-not $write.ok) {
441	      if ($write.reason -eq 'push_rejected_non_ff') { Stop-WireCutDispatch 'WOC-D007' 'Observe reconcile push rejected (non-fast-forward).' }
442	      Stop-WireCutDispatch 'WOC-D006' "Observe reconcile write failed: $($write.reason)"
443	    }
444	    Emit-WireCutDispatchSuccess "observe-retry complete effect_key=$EffectKey new_attempt_id=$newAttempt status=$reconciledStatus"
445	  }
446	
447	  Stop-WireCutDispatch 'WOC-D099' "Unsupported mode $Mode."
448	} finally {
449	  if ($mutexHeld) { $mutex.ReleaseMutex() | Out-Null }
450	  if ($null -ne $mutex) { $mutex.Dispose() }
451	}
452

file.content:
[CmdletBinding()]
param(
  [ValidateSet('Initialize', 'Tick', 'Transition', 'ObserveRetry', 'RegisterSynthetic', 'ReplayVerify', 'RebuildSnapshot', 'TickPreflight')]
  [string]$Mode = 'Tick',

  [string]$Workspace = '',
  [string]$ControlWorktree = '',
  [string]$GitCommand = 'git',
  [string]$NodeCommand = 'node',
  [string]$MutexName = 'Global\aal-agent-claims',
  [string]$OwnerSession = '',
  [int]$LeaseMinutes = 360,
  [string]$EffectKey = '',
  [string]$ToStatus = '',
  [Nullable[int]]$ExpectedAttemptId,
  [Nullable[int]]$ExpectedSequence,
  [string]$ExpectedStatus,
  [string]$PackageClass = 'wire',
  [string]$CompletionEvidencePath = '',
  [string]$ObserveResultPath = '',
  [string[]]$SyntheticLeaves = @(),
  [switch]$TestMode,
  [switch]$SkipMutex,
  [switch]$NoPush
)

$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'wire-or-cut-dispatch-core.ps1')
$script:WireCutDispatchInvocationParameters = $PSBoundParameters

function Stop-WireCutDispatch {
  param(
    [Parameter(Mandatory)][string]$Code,
    [Parameter(Mandatory)][string]$Message
  )
  Write-Output "[$Code] $Message"
  exit 1
}

function Emit-WireCutDispatchSuccess {
  param([string]$Message)
  Write-Output "[WOC-D000] $Message"
  exit 0
}

$script:WireCutDispatchTestMode = $false
if ($TestMode) {
  if ($env:WIRE_OR_CUT_DISPATCHER_TEST -ne '1') {
    Stop-WireCutDispatch 'WOC-D099' 'TestMode requires WIRE_OR_CUT_DISPATCHER_TEST=1.'
  }
  $script:WireCutDispatchTestMode = $true
} else {
  if ($GitCommand -ne 'git' -or $NodeCommand -ne 'node' -or $MutexName -ne 'Global\aal-agent-claims') {
    Stop-WireCutDispatch 'WOC-D099' 'Production git/node/mutex overrides are not permitted outside TestMode.'
  }
}
if (($SkipMutex -or $NoPush) -and -not $script:WireCutDispatchTestMode) {
  Stop-WireCutDispatch 'WOC-D099' 'SkipMutex and NoPush are test-only dispatcher controls.'
}

function Assert-WireCutExpectedCas {
  param(
    [Parameter(Mandatory)]$Entry
  )
  foreach ($name in @('ExpectedStatus', 'ExpectedAttemptId', 'ExpectedSequence')) {
    if (-not $script:WireCutDispatchInvocationParameters.ContainsKey($name)) {
      Stop-WireCutDispatch 'WOC-D006' 'Every mutation requires expected status, attempt_id, and transition sequence.'
    }
  }
  if ([string]::IsNullOrWhiteSpace($ExpectedStatus) -or
      $null -eq $ExpectedAttemptId -or [int]$ExpectedAttemptId -lt 1 -or
      $null -eq $ExpectedSequence -or [int]$ExpectedSequence -lt 0) {
    Stop-WireCutDispatch 'WOC-D006' 'CAS expectation fields are invalid.'
  }
  if ([string]$Entry.status -ne $ExpectedStatus) {
    Stop-WireCutDispatch 'WOC-D006' 'CAS status mismatch.'
  }
  if ([int]$Entry.attempt_id -ne [int]$ExpectedAttemptId) {
    Stop-WireCutDispatch 'WOC-D006' 'CAS attempt_id mismatch.'
  }
  if ([int]$Entry.last_transition_sequence -ne [int]$ExpectedSequence) {
    Stop-WireCutDispatch 'WOC-D006' 'CAS sequence mismatch.'
  }
}

function Assert-WireCutExpectedAbsentCas {
  foreach ($name in @('ExpectedStatus', 'ExpectedAttemptId', 'ExpectedSequence')) {
    if (-not $script:WireCutDispatchInvocationParameters.ContainsKey($name)) {
      Stop-WireCutDispatch 'WOC-D006' 'Synthetic registration requires an explicit absent-entry CAS tuple.'
    }
  }
  if ($ExpectedStatus -ne '__absent__' -or [int]$ExpectedAttemptId -ne 0 -or [int]$ExpectedSequence -ne 0) {
    Stop-WireCutDispatch 'WOC-D006' 'Synthetic registration CAS tuple must be __absent__,0,0.'
  }
}

if ([string]::IsNullOrWhiteSpace($Workspace)) {
  Stop-WireCutDispatch 'WOC-D001' 'Workspace is required.'
}
$resolvedWorkspace = Resolve-WireCutExactPath $Workspace
if (-not $resolvedWorkspace) {
  Stop-WireCutDispatch 'WOC-D001' 'Workspace path cannot be resolved.'
}
$top = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
  'rev-parse', '--show-toplevel'
)
$resolvedTop = if ($top.ExitCode -eq 0) { Resolve-WireCutExactPath $top.Output } else { $null }
if ($top.ExitCode -ne 0 -or -not $resolvedTop -or
    -not $resolvedTop.Equals($resolvedWorkspace, [StringComparison]::OrdinalIgnoreCase)) {
  Stop-WireCutDispatch 'WOC-D001' 'Workspace is not the exact root of a git worktree.'
}

$mutex = $null
$mutexHeld = $false
if (-not $SkipMutex) {
  $mutex = [System.Threading.Mutex]::new($false, $MutexName)
  try {
    try { $mutexHeld = $mutex.WaitOne(0) }
    catch [System.Threading.AbandonedMutexException] { $mutexHeld = $true }
    if (-not $mutexHeld) { Stop-WireCutDispatch 'WOC-D001' 'Another dispatcher instance holds the mutex.' }
  } catch {
    Stop-WireCutDispatch 'WOC-D001' 'Could not acquire dispatcher mutex.'
  }
}

try {
  $preflightMode = if ($Mode -eq 'Initialize') { 'Initialize' } else { 'Tick' }
  if ($Mode -in @('Initialize')) {
    $localState = Test-WireCutLocalInitializationState -GitCommand $GitCommand -Workspace $resolvedWorkspace
    if (-not $localState.ok) {
      Stop-WireCutDispatch 'WOC-D008' "Initialize is one-shot and local $($localState.reason) state already exists."
    }
    $status = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
      'status', '--porcelain=v1'
    )
    if ($status.ExitCode -ne 0 -or -not [string]::IsNullOrWhiteSpace($status.Output)) {
      Stop-WireCutDispatch 'WOC-D013' 'Workspace is dirty; initialization refuses to proceed.'
    }
    $initCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Initialize'
    if (-not $initCheck.ok) { Stop-WireCutDispatch $initCheck.code $initCheck.message }
    $planCommit = $initCheck.origin_main
    $registryPath = Join-Path $resolvedWorkspace $script:WireCutDispatchRegistryRelative
    $digest = Get-WireCutCanonicalTextSha256 -Path $registryPath
    $registry = Get-Content -Raw -LiteralPath $registryPath -Encoding utf8 | ConvertFrom-Json
    $packages = [ordered]@{}
    foreach ($wp in @($registry.work_packages)) {
      if (-not $wp.id) { continue }
      $seed = if ($wp.PSObject.Properties['status']) { [string]$wp.status } else { 'pending' }
      $packages[$wp.id] = New-WireCutPackageRuntimeEntry -EffectKey $wp.id -SeedStatus $seed
    }
    $snapshot = [ordered]@{
      schema_version = 1
      plan_binding = [ordered]@{
        plan_commit = $planCommit
        registry_sha256 = $digest
      }
      last_transition_sequence = 0
      work_packages = (Sort-WireCutWorkPackages -Packages $packages)
    }
    $stateDir = Split-Path -Parent (Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative)
    if (-not (Test-Path -LiteralPath $stateDir -PathType Container)) {
      New-Item -ItemType Directory -Path $stateDir -Force | Out-Null
    }
    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
    $branch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
      'checkout', '-b', $script:WireCutDispatchStateBranch
    )
    if ($branch.ExitCode -ne 0) { Stop-WireCutDispatch 'WOC-D008' 'Could not create local wirecut-state branch.' }
    $initEvent = [ordered]@{
      sequence = 0
      at = Get-WireCutUtcIsoNow
      type = 'sequence_init'
      plan_commit = $planCommit
      registry_sha256 = $digest
    }
    Add-WireCutDispatchEventLine -EventsPath $eventsPath -Event $initEvent
    Write-WireCutCanonicalJson -Path $snapshotPath -Object $snapshot
    $add = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
      'add', '--',
      ($script:WireCutDispatchStateRelative -replace '\\','/'),
      ($script:WireCutDispatchEventsRelative -replace '\\','/')
    )
    if ($add.ExitCode -ne 0) { Stop-WireCutDispatch 'WOC-D008' 'Could not stage initialization state.' }
    $commit = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
      'commit', '-m', 'wire-or-cut: initialize campaign state sequence 0'
    )
    if ($commit.ExitCode -ne 0) { Stop-WireCutDispatch 'WOC-D008' 'Could not commit initialization state.' }
  if (-not $NoPush) {
      $push = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Arguments @(
        'push', '-u', 'origin', "HEAD:refs/heads/$($script:WireCutDispatchStateBranch)"
      )
      if ($push.ExitCode -ne 0) { Stop-WireCutDispatch 'WOC-D007' 'Initialization push was rejected (non-fast-forward).' }
    }
    if ([string]::IsNullOrWhiteSpace($ControlWorktree)) {
      Stop-WireCutDispatch 'WOC-D014' 'Initialize requires a dedicated clean control worktree for wirecut-state handoff.'
    }
    $handoff = Invoke-WireCutControlWorktreeHandoff -GitCommand $GitCommand -ControlWorktree $ControlWorktree
    if (-not $handoff.ok) { Stop-WireCutDispatch $handoff.code $handoff.message }
    Emit-WireCutDispatchSuccess "initialization complete; state_commit=$($handoff.state_commit)"
  }

  if ($Mode -eq 'TickPreflight') {
    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
    Emit-WireCutDispatchSuccess "tick preflight coherent; plan_commit=$($tickCheck.plan_commit)"
  }

  if ($Mode -eq 'Tick') {
    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
    $expired = @()
    foreach ($name in (Get-WireCutWorkPackageProperties -WorkPackages $tickCheck.snapshot.work_packages)) {
      $entry = Get-WireCutWorkPackageEntry -WorkPackages $tickCheck.snapshot.work_packages -EffectKey $name
      if ($null -ne $entry.lease -and -not (Test-WireCutLeaseLive -Lease $entry.lease)) {
        $expired += [string]$entry.effect_key
      }
    }
    [ordered]@{
      code = 'WOC-D000'
      kind = 'wire-or-cut-tick'
      expired_effect_keys = @($expired)
      expired_lease_count = @($expired).Count
      required_action = 'ObserveRetry'
    } | ConvertTo-Json -Compress | Write-Output
    exit 0
  }

  if ($Mode -eq 'RebuildSnapshot') {
    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
    if (-not (Test-Path -LiteralPath $eventsPath -PathType Leaf)) {
      Stop-WireCutDispatch 'WOC-D009' 'Event ledger file is missing.'
    }
    $events = Read-WireCutDispatchEvents -EventsPath $eventsPath
    if ($null -eq $events) { Stop-WireCutDispatch 'WOC-D009' 'Event ledger is corrupt.' }
    if (@($events).Count -lt 1) {
      $raw = [IO.File]::ReadAllText($eventsPath)
      Stop-WireCutDispatch 'WOC-D009' "Event ledger is empty (bytes=$($raw.Length))."
    }
    $init = $events | Where-Object { [string]$_.type -eq 'sequence_init' } | Select-Object -First 1
    if ($null -eq $init) { Stop-WireCutDispatch 'WOC-D009' 'Initialization event is missing.' }
    $planCommit = [string]$init.plan_commit
    $registry = Read-WireCutDispatchRegistryAtCommit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Commit $planCommit
    if ($null -eq $registry) { Stop-WireCutDispatch 'WOC-D004' 'Bound plan registry cannot be read for rebuild.' }
    $binding = [ordered]@{
      plan_commit = $planCommit
      registry_sha256 = [string]$init.registry_sha256
    }
    $rebuilt = Invoke-WireCutReplayEvents -Registry $registry -PlanBinding $binding -Events $events
    if ($null -eq $rebuilt) { Stop-WireCutDispatch 'WOC-D009' 'Replay rebuild failed.' }
    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
    Write-WireCutCanonicalJson -Path $snapshotPath -Object $rebuilt
    Emit-WireCutDispatchSuccess 'rebuild snapshot from events complete'
  }

  if ($Mode -eq 'ReplayVerify') {
    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
    $events = Read-WireCutDispatchEvents -EventsPath $eventsPath
    $rebuilt = Invoke-WireCutReplayEvents -Registry $tickCheck.registry -PlanBinding $tickCheck.snapshot.plan_binding -Events $events
    if ($null -eq $rebuilt) { Stop-WireCutDispatch 'WOC-D009' 'Replay rebuild failed.' }
    $left = Get-WireCutCanonicalJsonSha256 -Object (Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot)
    $right = Get-WireCutCanonicalJsonSha256 -Object $rebuilt
    if ($left -ne $right) { Stop-WireCutDispatch 'WOC-D009' 'Replay digest does not match snapshot.' }
    Emit-WireCutDispatchSuccess 'replay verify passed'
  }

  if ($Mode -eq 'RegisterSynthetic') {
    if (-not $TestMode) { Stop-WireCutDispatch 'WOC-D099' 'RegisterSynthetic is test-only.' }
    if ($SyntheticLeaves.Count -lt 1) { Stop-WireCutDispatch 'WOC-D011' 'SyntheticLeaves is required.' }
    Assert-WireCutExpectedAbsentCas
    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
    $snapshot = Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot
    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
    $events = @()
    foreach ($leaf in @($SyntheticLeaves)) {
      if (Test-WireCutWorkPackageExists -WorkPackages $snapshot.work_packages -EffectKey $leaf) { continue }
      Set-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $leaf -Entry (New-WireCutPackageRuntimeEntry -EffectKey $leaf -SeedStatus 'pending')
      $entry = Get-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $leaf
      $entry | Add-Member -NotePropertyName 'class' -NotePropertyValue $PackageClass -Force
      $events += [ordered]@{
        type = 'synthetic_register'
        effect_key = $leaf
        class = $PackageClass
      }
    }
    if ($events.Count -lt 1) { Stop-WireCutDispatch 'WOC-D011' 'Synthetic leaf already exists.' }
    $write = Invoke-WireCutDispatchStateWrite -GitCommand $GitCommand -Workspace $resolvedWorkspace `
      -SnapshotPath $snapshotPath -EventsPath $eventsPath -SnapshotObject $snapshot -EventObjects $events `
      -CommitMessage 'wire-or-cut: register synthetic leaves'
    if (-not $write.ok) {
      if ($write.reason -eq 'push_rejected_non_ff') { Stop-WireCutDispatch 'WOC-D007' 'Synthetic register push rejected (non-fast-forward).' }
      Stop-WireCutDispatch 'WOC-D006' "Synthetic register failed: $($write.reason)"
    }
    Emit-WireCutDispatchSuccess ("synthetic leaves registered: " + ($SyntheticLeaves -join ','))
  }

  if ($Mode -eq 'Transition') {
    if ([string]::IsNullOrWhiteSpace($EffectKey) -or [string]::IsNullOrWhiteSpace($ToStatus)) {
      Stop-WireCutDispatch 'WOC-D011' 'Transition requires EffectKey and ToStatus.'
    }
    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
    $snapshot = Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot
    if (-not (Test-WireCutWorkPackageExists -WorkPackages $snapshot.work_packages -EffectKey $EffectKey)) {
      Stop-WireCutDispatch 'WOC-D011' "Unknown effect_key $EffectKey."
    }
    $entry = Get-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $EffectKey
    Assert-WireCutExpectedCas -Entry $entry
    if ($null -ne $entry.lease -and (Test-WireCutLeaseLive -Lease $entry.lease) -and $ToStatus -eq 'leased') {
      Stop-WireCutDispatch 'WOC-D012' 'Live unexpired lease blocks redispatch.'
    }
    # Registry waivers[] are an operator governance mechanism; this dispatcher
    # has no waiver mutation verb, so it never manufactures a waived status.
    $valid = @('pending', 'leased', 'dispatched', 'reviewing', 'blocked', 'done')
    if ($valid -notcontains $ToStatus) { Stop-WireCutDispatch 'WOC-D011' "Invalid target status $ToStatus." }
    $fromStatus = [string]$entry.status
    $allowed = @{
      pending = @('leased')
      leased = @('dispatched')
      dispatched = @('reviewing')
      reviewing = @('done', 'blocked')
    }
    if (-not $allowed.ContainsKey($fromStatus) -or $allowed[$fromStatus] -notcontains $ToStatus) {
      Stop-WireCutDispatch 'WOC-D011' "Transition $fromStatus -> $ToStatus is not allowed."
    }
    $event = [ordered]@{
      type = 'status_transition'
      effect_key = $EffectKey
      from_status = $fromStatus
      to_status = $ToStatus
      attempt_id = [int]$entry.attempt_id
    }
    $entry.status = $ToStatus
    if ($ToStatus -eq 'leased') {
      if ([string]::IsNullOrWhiteSpace($OwnerSession)) {
        Stop-WireCutDispatch 'WOC-D011' 'Lease transition requires OwnerSession.'
      }
      $expires = [DateTime]::UtcNow.AddMinutes($LeaseMinutes).ToString('o')
      if ($TestMode -and $LeaseMinutes -lt 0) {
        $expires = [DateTime]::UtcNow.AddMinutes($LeaseMinutes).ToString('o')
      }
      $lease = [ordered]@{
        owner_session = $OwnerSession
        attempt_id = [int]$entry.attempt_id
        expires_at = $expires
        effect_key = $EffectKey
      }
      $entry.lease = $lease
      $event.lease = $lease
    } elseif ($ToStatus -in @('dispatched', 'reviewing', 'done', 'blocked')) {
      if ($null -ne $entry.lease) { $event.clear_lease = $true }
      $entry.lease = $null
    }
    if ($ToStatus -eq 'done') {
      $class = $PackageClass
      if ($entry.PSObject.Properties['class']) { $class = [string]$entry.class }
      if ([string]::IsNullOrWhiteSpace($CompletionEvidencePath) -or -not (Test-Path -LiteralPath $CompletionEvidencePath -PathType Leaf)) {
        Stop-WireCutDispatch 'WOC-D011' 'Done transition requires CompletionEvidencePath.'
      }
      $evidence = Get-Content -Raw -LiteralPath $CompletionEvidencePath -Encoding utf8 | ConvertFrom-Json
      if (-not (Test-WireCutCompletionEvidence -Registry $tickCheck.registry -Class $class -Evidence $evidence -PackageId $EffectKey)) {
        Stop-WireCutDispatch 'WOC-D011' 'Completion evidence does not satisfy the class-typed contract.'
      }
      $entry.completion_evidence_refs = $evidence
      $event.completion_evidence_refs = $evidence
    }
    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
    if ($NoPush) {
      $mutation = Write-WireCutDispatchStateMutation -SnapshotPath $snapshotPath -EventsPath $eventsPath `
        -SnapshotObject $snapshot -EventObjects @($event)
      Emit-WireCutDispatchSuccess "transition staged locally $fromStatus->$ToStatus effect_key=$EffectKey sequence=$($mutation.sequence)"
    } else {
      $write = Invoke-WireCutDispatchStateWrite -GitCommand $GitCommand -Workspace $resolvedWorkspace `
        -SnapshotPath $snapshotPath -EventsPath $eventsPath -SnapshotObject $snapshot -EventObjects @($event) `
        -CommitMessage "wire-or-cut: $EffectKey $fromStatus->$ToStatus"
      if (-not $write.ok) {
        if ($write.reason -eq 'push_rejected_non_ff') { Stop-WireCutDispatch 'WOC-D007' 'Transition push rejected (non-fast-forward); re-read required.' }
        Stop-WireCutDispatch 'WOC-D006' "Transition write failed: $($write.reason)"
      }
      Emit-WireCutDispatchSuccess "transition $fromStatus->$ToStatus effect_key=$EffectKey sequence=$($write.sequence)"
    }
  }

  if ($Mode -eq 'ObserveRetry') {
    if ([string]::IsNullOrWhiteSpace($EffectKey)) { Stop-WireCutDispatch 'WOC-D011' 'ObserveRetry requires EffectKey.' }
    if ([string]::IsNullOrWhiteSpace($ObserveResultPath) -or -not (Test-Path -LiteralPath $ObserveResultPath -PathType Leaf)) {
      Stop-WireCutDispatch 'WOC-D013' 'ObserveRetry requires ObserveResultPath.'
    }
    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
    $snapshot = Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot
    if (-not (Test-WireCutWorkPackageExists -WorkPackages $snapshot.work_packages -EffectKey $EffectKey)) {
      Stop-WireCutDispatch 'WOC-D011' "Unknown effect_key $EffectKey."
    }
    $entry = Get-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $EffectKey
    Assert-WireCutExpectedCas -Entry $entry
    $liveLease = $null -ne $entry.lease -and (Test-WireCutLeaseLive -Lease $entry.lease)
    if ($liveLease) {
      Stop-WireCutDispatch 'WOC-D012' 'Live unexpired lease blocks observe-before-retry.'
    }
    $expiredLease = $null -ne $entry.lease
    if ([string]$entry.status -ne 'blocked' -and -not $expiredLease) {
      Stop-WireCutDispatch 'WOC-D013' 'ObserveRetry requires a blocked package or an expired lease.'
    }
    $observe = Get-Content -Raw -LiteralPath $ObserveResultPath -Encoding utf8 | ConvertFrom-Json
    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
    $oldAttempt = [int]$entry.attempt_id
    $newAttempt = $oldAttempt + 1
    $entry.status = 'blocked'
    $entry.lease = $null
    $tombstone = [ordered]@{
      type = 'attempt_tombstone'
      effect_key = $EffectKey
      attempt_id = $oldAttempt
      reason = if ($expiredLease) { 'lease_expired' } else { 'blocked_observe_retry' }
    }
    $reconciledStatus = 'pending'
    if ($observe.PSObject.Properties['external_done'] -and [bool]$observe.external_done) {
      $reconciledStatus = 'reviewing'
    }
    $reconcile = [ordered]@{
      type = 'observe_reconcile'
      effect_key = $EffectKey
      to_status = $reconciledStatus
      new_attempt_id = $newAttempt
      observed = $observe
    }
    $entry.status = $reconciledStatus
    $entry.attempt_id = $newAttempt
    $entry.lease = $null
    $write = Invoke-WireCutDispatchStateWrite -GitCommand $GitCommand -Workspace $resolvedWorkspace `
      -SnapshotPath $snapshotPath -EventsPath $eventsPath -SnapshotObject $snapshot -EventObjects @($tombstone, $reconcile) `
      -CommitMessage "wire-or-cut: observe-reconcile $EffectKey -> $reconciledStatus fence=$newAttempt"
    if (-not $write.ok) {
      if ($write.reason -eq 'push_rejected_non_ff') { Stop-WireCutDispatch 'WOC-D007' 'Observe reconcile push rejected (non-fast-forward).' }
      Stop-WireCutDispatch 'WOC-D006' "Observe reconcile write failed: $($write.reason)"
    }
    Emit-WireCutDispatchSuccess "observe-retry complete effect_key=$EffectKey new_attempt_id=$newAttempt status=$reconciledStatus"
  }

  Stop-WireCutDispatch 'WOC-D099' "Unsupported mode $Mode."
} finally {
  if ($mutexHeld) { $mutex.ReleaseMutex() | Out-Null }
  if ($null -ne $mutex) { $mutex.Dispose() }
}

