323	function Invoke-WireCutReplayEvents {
324	  param(
325	    [Parameter(Mandatory)]$Registry,
326	    [Parameter(Mandatory)]$PlanBinding,
327	    [Parameter(Mandatory)][array]$Events
328	  )
329	  $packages = [ordered]@{}
330	  foreach ($wp in @($Registry.work_packages)) {
331	    if (-not $wp.id) { continue }
332	    $seed = if ($wp.PSObject.Properties['status']) { [string]$wp.status } else { 'pending' }
333	    $packages[$wp.id] = New-WireCutPackageRuntimeEntry -EffectKey $wp.id -SeedStatus $seed -AttemptId 1 -Sequence 0
334	  }
335	  $sequence = -1
336	  foreach ($event in ($Events | Sort-Object { [int]$_.sequence })) {
337	    $seq = [int]$event.sequence
338	    $type = [string]$event.type
339	    if ($type -eq 'sequence_init') {
340	      if ($seq -ne 0) { return $null }
341	      $sequence = 0
342	      continue
343	    }
344	    if ($seq -ne ($sequence + 1)) { return $null }
345	    $sequence = $seq
346	    if ($type -eq 'synthetic_register') {
347	      $effectKey = [string]$event.effect_key
348	      $class = [string]$event.class
349	      if (-not $packages.Contains($effectKey)) {
350	        $packages[$effectKey] = New-WireCutPackageRuntimeEntry -EffectKey $effectKey -SeedStatus 'pending'
351	        $packages[$effectKey] | Add-Member -NotePropertyName 'class' -NotePropertyValue $class -Force
352	        $packages[$effectKey].last_transition_sequence = $seq
353	      }
354	      continue
355	    }
356	    $effectKey = [string]$event.effect_key
357	    if (-not $packages.Contains($effectKey)) { return $null }
358	    $entry = $packages[$effectKey]
359	    if ($type -eq 'status_transition') {
360	      $entry.status = [string]$event.to_status
361	      $entry.attempt_id = [int]$event.attempt_id
362	      $entry.last_transition_sequence = $seq
363	      if ($event.PSObject.Properties['lease'] -and $null -ne $event.lease) {
364	        $entry.lease = [ordered]@{
365	          owner_session = [string]$event.lease.owner_session
366	          attempt_id = [int]$event.lease.attempt_id
367	          expires_at = [string]$event.lease.expires_at
368	          effect_key = [string]$event.lease.effect_key
369	        }
370	      } elseif ($event.PSObject.Properties['clear_lease'] -and $event.clear_lease) {
371	        $entry.lease = $null
372	      }
373	      if ($event.PSObject.Properties['completion_evidence_refs'] -and $null -ne $event.completion_evidence_refs) {
374	        $entry.completion_evidence_refs = $event.completion_evidence_refs
375	      }
376	    } elseif ($type -eq 'attempt_tombstone') {
377	      if ([int]$event.attempt_id -ne [int]$entry.attempt_id) { return $null }
378	      $entry.lease = $null
379	      $entry.status = 'blocked'
380	      $entry.last_transition_sequence = $seq
381	    } elseif ($type -eq 'observe_reconcile') {
382	      $entry.status = [string]$event.to_status
383	      $entry.attempt_id = [int]$event.new_attempt_id
384	      $entry.lease = $null
385	      $entry.last_transition_sequence = $seq
386	    }
387	  }
388	  return [ordered]@{
389	    schema_version = 1
390	    plan_binding = [ordered]@{
391	      plan_commit = [string]$PlanBinding.plan_commit
392	      registry_sha256 = [string]$PlanBinding.registry_sha256
393	    }
394	    last_transition_sequence = $sequence
395	    work_packages = (Sort-WireCutWorkPackages -Packages $packages)
396	  }
397	}
