521	    ($script:WireCutDispatchEventsRelative -replace '\\','/')
522	  )
523	  if ($add.ExitCode -ne 0) { return [pscustomobject]@{ ok = $false; reason = 'git_add_failed'; sequence = $mutation.sequence } }
524	  $commit = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
525	    'commit', '-m', $CommitMessage
526	  )
527	  if ($commit.ExitCode -ne 0) { return [pscustomobject]@{ ok = $false; reason = 'git_commit_failed'; sequence = $mutation.sequence } }
528	  $push = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
529	    'push', 'origin', "HEAD:refs/heads/$($script:WireCutDispatchStateBranch)"
530	  )
531	  if ($push.ExitCode -ne 0) {
532	    return [pscustomobject]@{ ok = $false; reason = 'push_rejected_non_ff'; sequence = $mutation.sequence; push_output = $push.Output }
533	  }
534	  return [pscustomobject]@{ ok = $true; reason = ''; sequence = $mutation.sequence }
535	}
