537	function Invoke-WireCutDispatchTickPreflight {
538	  param(
539	    [Parameter(Mandatory)][string]$GitCommand,
540	    [Parameter(Mandatory)][string]$NodeCommand,
541	    [Parameter(Mandatory)][string]$Workspace,
542	    [ValidateSet('Initialize', 'Tick')]
543	    [string]$Mode
544	  )
545	  $fetchRefs = if ($Mode -eq 'Initialize') { @('main') } else { @('main', $script:WireCutDispatchStateBranch) }
546	  $fetchArgs = @('fetch', '--no-tags', 'origin') + $fetchRefs
547	  $fetch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments $fetchArgs
548	  if ($fetch.ExitCode -ne 0) {
549	    return [pscustomobject]@{ ok = $false; code = 'WOC-D002'; message = 'Could not fetch required authority refs.' }
550	  }
551	  $head = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @('rev-parse', 'HEAD')
552	  $main = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @('rev-parse', $script:WireCutDispatchPlanRemoteRef)
553	  if ($head.ExitCode -ne 0 -or $main.ExitCode -ne 0) {
554	    return [pscustomobject]@{ ok = $false; code = 'WOC-D002'; message = 'HEAD or origin/main cannot be resolved after fetch.' }
555	  }
556	  $headCommit = $head.Output.Trim()
557	  $originMain = $main.Output.Trim()
558	  if ($Mode -eq 'Initialize') {
559	    if ($headCommit -ne $originMain) {
560	      return [pscustomobject]@{ ok = $false; code = 'WOC-D003'; message = 'Initialize requires clean HEAD to equal exact origin/main.' }
561	    }
562	    $exists = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
563	      'ls-remote', '--exit-code', '--heads', 'origin', "refs/heads/$($script:WireCutDispatchStateBranch)"
564	    )
565	    if ($exists.ExitCode -eq 0) {
566	      return [pscustomobject]@{ ok = $false; code = 'WOC-D008'; message = 'Initialize is one-shot and wirecut-state already exists on origin.' }
567	    }
568	    if ($exists.ExitCode -ne 2) {
569	      return [pscustomobject]@{ ok = $false; code = 'WOC-D002'; message = 'Could not prove wirecut-state is absent on origin.' }
570	    }
571	    return [pscustomobject]@{ ok = $true; code = 'WOC-D000'; head_commit = $headCommit; origin_main = $originMain }
572	  }
573	  $branch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
574	    'symbolic-ref', '--quiet', '--short', 'HEAD'
575	  )
576	  $state = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
577	    'rev-parse', $script:WireCutDispatchStateRemoteRef
578	  )
579	  if ($branch.ExitCode -ne 0 -or $branch.Output.Trim() -ne $script:WireCutDispatchStateBranch -or
580	      $state.ExitCode -ne 0 -or $headCommit -ne $state.Output.Trim()) {
581	    return [pscustomobject]@{ ok = $false; code = 'WOC-D003'; message = 'Tick requires local wirecut-state to equal exact origin/wirecut-state.' }
582	  }
583	  $snapshotPath = Join-Path $Workspace $script:WireCutDispatchStateRelative
584	  $snapshot = Read-WireCutDispatchSnapshot -SnapshotPath $snapshotPath
585	  if ($null -eq $snapshot) {
586	    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'Runtime-state snapshot is missing or invalid.' }
587	  }
588	  $planCommit = [string]$snapshot.plan_binding.plan_commit
589	  $expectedDigest = ([string]$snapshot.plan_binding.registry_sha256).ToLowerInvariant()
590	  $registryPath = Join-Path $Workspace $script:WireCutDispatchRegistryRelative
591	  if (-not (Test-Path -LiteralPath $registryPath -PathType Leaf)) {
592	    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'Registry file is missing in the worktree.' }
593	  }
594	  $actualDigest = Get-WireCutCanonicalTextSha256 -Path $registryPath
595	  if ($planCommit -notmatch '^[0-9a-f]{40}$' -or $expectedDigest -notmatch '^[0-9a-f]{64}$' -or $actualDigest -ne $expectedDigest) {
596	    return [pscustomobject]@{ ok = $false; code = 'WOC-D010'; message = 'Runtime-state plan binding does not match the registry digest.' }
597	  }
598	  $commitCheck = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
599	    'cat-file', '-e', "${planCommit}^{commit}"
600	  )
601	  if ($commitCheck.ExitCode -ne 0) {
602	    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'plan_commit is not a known commit in this worktree.' }
603	  }
604	  $ancestry = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
605	    'merge-base', '--is-ancestor', $planCommit, $originMain
606	  )
607	  if ($ancestry.ExitCode -ne 0) {
608	    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'plan_commit is not an ancestor of current origin/main.' }
609	  }
610	  $mainRegistry = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
611	    'diff', '--quiet', $planCommit, $originMain, '--', ($script:WireCutDispatchRegistryRelative -replace '\\','/')
612	  )
613	  if ($mainRegistry.ExitCode -ne 0) {
614	    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'The plan registry changed on origin/main; explicit migration is required.' }
615	  }
616	  $carriedRegistry = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
617	    'diff', '--quiet', $planCommit, '--', ($script:WireCutDispatchRegistryRelative -replace '\\','/')
618	  )
619	  if ($carriedRegistry.ExitCode -ne 0) {
620	    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'wirecut-state carries a registry that differs from its bound plan commit.' }
621	  }
622	  $validatorPath = Join-Path $Workspace $script:WireCutDispatchValidatorRelative
623	  $prior = Get-Location
624	  try {
625	    Set-Location -LiteralPath $Workspace
626	    $ErrorActionPreference = 'Continue'
627	    $validatorOutput = @(& $NodeCommand $validatorPath 2>&1)
628	    $validatorExit = if ($null -eq $LASTEXITCODE) { 126 } else { [int]$LASTEXITCODE }
629	    $validatorText = ($validatorOutput | Out-String).TrimEnd()
630	  } finally {
631	    Set-Location -LiteralPath $prior
632	  }
633	  if ($validatorExit -ne 0 -or $validatorText -notmatch 'WIRE-OR-CUT VALIDATOR: coherent') {
634	    return [pscustomobject]@{ ok = $false; code = 'WOC-D005'; message = 'Registry validator failed.' }
635	  }
636	  $eventsPath = Join-Path $Workspace $script:WireCutDispatchEventsRelative
637	  $events = Read-WireCutDispatchEvents -EventsPath $eventsPath
638	  if ($null -eq $events) {
639	    return [pscustomobject]@{ ok = $false; code = 'WOC-D009'; message = 'Event ledger is corrupt.' }
640	  }
641	  $registry = Read-WireCutDispatchRegistryAtCommit -GitCommand $GitCommand -Workspace $Workspace -Commit $planCommit
642	  if ($null -eq $registry) {
643	    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'Bound plan registry cannot be read.' }
644	  }
645	  if (-not (Test-WireCutSnapshotMatchesEvents -Registry $registry -Snapshot $snapshot -Events $events)) {
646	    return [pscustomobject]@{ ok = $false; code = 'WOC-D009'; message = 'Events and snapshot disagree; replay rebuild mismatch.' }
647	  }
648	  return [pscustomobject]@{
649	    ok = $true
650	    code = 'WOC-D000'
651	    head_commit = $headCommit
652	    origin_main = $originMain
653	    plan_commit = $planCommit
654	    registry = $registry
655	    snapshot = $snapshot
656	    events = $events
657	  }
658	}
