660	function Invoke-WireCutControlWorktreeHandoff {
661	  param(
662	    [Parameter(Mandatory)][string]$GitCommand,
663	    [Parameter(Mandatory)][string]$ControlWorktree
664	  )
665	  $status = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
666	    'status', '--porcelain=v1'
667	  )
668	  if ($status.ExitCode -ne 0 -or -not [string]::IsNullOrWhiteSpace($status.Output)) {
669	    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree is dirty before handoff.' }
670	  }
671	  $fetch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
672	    'fetch', '--no-tags', 'origin', 'main', $script:WireCutDispatchStateBranch
673	  )
674	  if ($fetch.ExitCode -ne 0) {
675	    return [pscustomobject]@{ ok = $false; code = 'WOC-D002'; message = 'Control worktree fetch failed.' }
676	  }
677	  $stateRef = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
678	    'rev-parse', $script:WireCutDispatchStateRemoteRef
679	  )
680	  if ($stateRef.ExitCode -ne 0) {
681	    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'origin/wirecut-state is not resolvable for handoff.' }
682	  }
683	  $target = $stateRef.Output.Trim()
684	  $localStateBranch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
685	    'show-ref', '--verify', '--quiet', "refs/heads/$($script:WireCutDispatchStateBranch)"
686	  )
687	  if ($localStateBranch.ExitCode -eq 0) {
688	    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree already has a local wirecut-state branch.' }
689	  }
690	  if ($localStateBranch.ExitCode -ne 1) {
691	    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree local branch state cannot be read.' }
692	  }
693	  $checkout = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
694	    'checkout', '-b', $script:WireCutDispatchStateBranch, $target
695	  )
696	  if ($checkout.ExitCode -ne 0) {
697	    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Could not switch control worktree to wirecut-state.' }
698	  }
699	  $head = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @('rev-parse', 'HEAD')
700	  if ($head.ExitCode -ne 0 -or $head.Output.Trim() -ne $target) {
701	    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree HEAD does not equal exact origin/wirecut-state after handoff.' }
702	  }
703	  $clean = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
704	    'status', '--porcelain=v1'
705	  )
706	  if ($clean.ExitCode -ne 0 -or -not [string]::IsNullOrWhiteSpace($clean.Output)) {
707	    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree is dirty after handoff.' }
708	  }
709	  return [pscustomobject]@{ ok = $true; code = 'WOC-D000'; state_commit = $target }
710	}
