# wire-or-cut-dispatch-core.ps1 — shared dispatcher primitives (WC-501A).
# Dot-sourced by wire-or-cut-dispatch.ps1; not executed directly.
# PowerShell 5.1-safe.

$script:WireCutDispatchRegistryRelative = 'specs\WIRE-OR-CUT-TASK-REGISTRY-2026-07-18.json'
$script:WireCutDispatchStateRelative = 'state\wire-or-cut\campaign-state.json'
$script:WireCutDispatchEventsRelative = 'state\wire-or-cut\events.jsonl'
$script:WireCutDispatchValidatorRelative = 'scripts\wire-or-cut-registry-validate.mjs'
$script:WireCutDispatchStateBranch = 'wirecut-state'
$script:WireCutDispatchPlanRemoteRef = 'refs/remotes/origin/main'
$script:WireCutDispatchStateRemoteRef = 'refs/remotes/origin/wirecut-state'

function Get-WireCutCanonicalTextSha256 {
  param([Parameter(Mandatory)][string]$Path)
  $text = [IO.File]::ReadAllText($Path)
  if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
  $text = $text.Replace("`r`n", "`n").Replace("`r", "`n")
  $bytes = [Text.UTF8Encoding]::new($false).GetBytes($text)
  $algorithm = [Security.Cryptography.SHA256]::Create()
  try { return ([BitConverter]::ToString($algorithm.ComputeHash($bytes))).Replace('-', '').ToLowerInvariant() }
  finally { $algorithm.Dispose() }
}

function Get-WireCutCanonicalJsonSha256 {
  param([Parameter(Mandatory)]$Object)
  $tmp = [IO.Path]::GetTempFileName()
  try {
    Write-WireCutCanonicalJson -Path $tmp -Object $Object
    return (Get-WireCutCanonicalTextSha256 -Path $tmp)
  } finally {
    if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force }
  }
}

function Write-WireCutCanonicalJson {
  param(
    [Parameter(Mandatory)][string]$Path,
    [Parameter(Mandatory)]$Object,
    [int]$Depth = 30,
    [switch]$FailBeforePublish
  )
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path -LiteralPath $dir -PathType Container)) {
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
  }
  $json = ($Object | ConvertTo-Json -Depth $Depth) + "`n"
  $json = $json.Replace("`r`n", "`n").Replace("`r", "`n")
  $bytes = [Text.UTF8Encoding]::new($false).GetBytes($json)
  $tmp = Join-Path $dir ('.' + [IO.Path]::GetFileName($Path) + '.' + $PID + '.' + [guid]::NewGuid().ToString('N') + '.tmp')
  $backup = $tmp + '.bak'
  try {
    $stream = [IO.File]::Open($tmp, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
    try {
      $stream.Write($bytes, 0, $bytes.Length)
      $stream.Flush($true)
    } finally {
      $stream.Dispose()
    }
    if ($FailBeforePublish) {
      if ($env:WIRE_OR_CUT_DISPATCHER_TEST -ne '1') {
        throw 'WOC-D015 fault injection is test-only.'
      }
      throw 'WOC-D015 simulated pre-publish snapshot failure.'
    }
    if (Test-Path -LiteralPath $Path -PathType Leaf) {
      [IO.File]::Replace($tmp, $Path, $backup)
    } else {
      [IO.File]::Move($tmp, $Path)
    }
  } finally {
    if (Test-Path -LiteralPath $tmp -PathType Leaf) {
      Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
    }
    if (Test-Path -LiteralPath $backup -PathType Leaf) {
      Remove-Item -LiteralPath $backup -Force -ErrorAction SilentlyContinue
    }
  }
}

function Invoke-WireCutDispatchGit {
  param(
    [Parameter(Mandatory)][string]$GitCommand,
    [Parameter(Mandatory)][string]$Workspace,
    [Parameter(Mandatory)][string[]]$Arguments
  )
  $prior = Get-Location
  $priorErrorAction = $ErrorActionPreference
  try {
    Set-Location -LiteralPath $Workspace
    $ErrorActionPreference = 'Continue'
    $output = @(& $GitCommand @Arguments 2>&1)
    $exitCode = $LASTEXITCODE
    [pscustomobject]@{
      ExitCode = if ($null -eq $exitCode) { 126 } else { [int]$exitCode }
      Output = ($output | Out-String).TrimEnd()
    }
  } catch {
    [pscustomobject]@{ ExitCode = 127; Output = $_.Exception.Message }
  } finally {
    $ErrorActionPreference = $priorErrorAction
    Set-Location -LiteralPath $prior
  }
}

function Resolve-WireCutExactPath {
  param([Parameter(Mandatory)][string]$Path)
  try { return (Resolve-Path -LiteralPath $Path -ErrorAction Stop).Path.TrimEnd('\') }
  catch { return $null }
}

function Test-WireCutLocalInitializationState {
  param(
    [Parameter(Mandatory)][string]$GitCommand,
    [Parameter(Mandatory)][string]$Workspace
  )
  $snapshotPath = Join-Path $Workspace $script:WireCutDispatchStateRelative
  if (Test-Path -LiteralPath $snapshotPath -PathType Leaf) {
    return [pscustomobject]@{ ok = $false; reason = 'snapshot' }
  }
  $eventsPath = Join-Path $Workspace $script:WireCutDispatchEventsRelative
  if (Test-Path -LiteralPath $eventsPath -PathType Leaf) {
    return [pscustomobject]@{ ok = $false; reason = 'events' }
  }
  $branch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'show-ref', '--verify', '--quiet', "refs/heads/$($script:WireCutDispatchStateBranch)"
  )
  if ($branch.ExitCode -eq 0) {
    return [pscustomobject]@{ ok = $false; reason = 'local_branch' }
  }
  if ($branch.ExitCode -ne 1) {
    return [pscustomobject]@{ ok = $false; reason = 'local_branch_unreadable' }
  }
  return [pscustomobject]@{ ok = $true; reason = '' }
}

function Read-WireCutDispatchRegistryAtCommit {
  param(
    [Parameter(Mandatory)][string]$GitCommand,
    [Parameter(Mandatory)][string]$Workspace,
    [Parameter(Mandatory)][string]$Commit
  )
  $show = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'show', "${Commit}:$($script:WireCutDispatchRegistryRelative -replace '\\','/')"
  )
  if ($show.ExitCode -ne 0) { return $null }
  try { return ($show.Output | ConvertFrom-Json) } catch { return $null }
}

function Get-WireCutCompletionKind {
  param(
    [Parameter(Mandatory)]$Registry,
    [Parameter(Mandatory)][string]$Class,
    [string]$PackageId = ''
  )
  if ($PackageId -and $Registry.completion_evidence.package_overrides.PSObject.Properties[$PackageId]) {
    return [string]$Registry.completion_evidence.package_overrides.$PackageId
  }
  $key = "class.$Class"
  if ($Registry.completion_evidence.resolution.PSObject.Properties[$key]) {
    return [string]$Registry.completion_evidence.resolution.$key
  }
  return ''
}

function Test-WireCutCompletionEvidence {
  param(
    [Parameter(Mandatory)]$Registry,
    [Parameter(Mandatory)][string]$Class,
    [Parameter(Mandatory)]$Evidence,
    [string]$PackageId = ''
  )
  $kindName = Get-WireCutCompletionKind -Registry $Registry -Class $Class -PackageId $PackageId
  if ([string]::IsNullOrWhiteSpace($kindName)) { return $false }
  $kind = $Registry.completion_evidence.kinds.$kindName
  if ($null -eq $kind) { return $false }
  foreach ($field in @($kind.required_fields)) {
    if (-not $Evidence.PSObject.Properties[$field]) { return $false }
    if ($null -eq $Evidence.$field) { return $false }
    if ($Evidence.$field -is [string] -and [string]::IsNullOrWhiteSpace($Evidence.$field)) { return $false }
  }
  return $true
}

function New-WireCutPackageRuntimeEntry {
  param(
    [Parameter(Mandatory)][string]$EffectKey,
    [Parameter(Mandatory)][string]$SeedStatus,
    [int]$AttemptId = 1,
    [int]$Sequence = 0
  )
  return [ordered]@{
    status = $SeedStatus
    attempt_id = $AttemptId
    effect_key = $EffectKey
    last_transition_sequence = $Sequence
    lease = $null
    completion_evidence_refs = $null
  }
}

function Read-WireCutDispatchEvents {
  param([Parameter(Mandatory)][string]$EventsPath)
  if (-not (Test-Path -LiteralPath $EventsPath -PathType Leaf)) { return @() }
  $text = [IO.File]::ReadAllText($EventsPath)
  if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
  return (Read-WireCutDispatchEventsFromText -Text $text)
}

function Read-WireCutDispatchSnapshot {
  param([Parameter(Mandatory)][string]$SnapshotPath)
  if (-not (Test-Path -LiteralPath $SnapshotPath -PathType Leaf)) { return $null }
  try { return (Get-Content -Raw -LiteralPath $SnapshotPath -Encoding utf8 | ConvertFrom-Json) }
  catch { return $null }
}

function Test-WireCutWorkPackageExists {
  param(
    [Parameter(Mandatory)]$WorkPackages,
    [Parameter(Mandatory)][string]$EffectKey
  )
  if ($WorkPackages -is [System.Collections.IDictionary]) {
    return $WorkPackages.Contains($EffectKey)
  }
  return $null -ne $WorkPackages.PSObject.Properties[$EffectKey]
}

function Get-WireCutWorkPackageEntry {
  param(
    [Parameter(Mandatory)]$WorkPackages,
    [Parameter(Mandatory)][string]$EffectKey
  )
  if ($WorkPackages -is [System.Collections.IDictionary]) {
    return $WorkPackages[$EffectKey]
  }
  return $WorkPackages.$EffectKey
}

function Set-WireCutWorkPackageEntry {
  param(
    [Parameter(Mandatory)]$WorkPackages,
    [Parameter(Mandatory)][string]$EffectKey,
    [Parameter(Mandatory)]$Entry
  )
  if ($WorkPackages -is [System.Collections.IDictionary]) {
    $WorkPackages[$EffectKey] = $Entry
    return
  }
  $WorkPackages | Add-Member -NotePropertyName $EffectKey -NotePropertyValue $Entry -Force
}

function Get-WireCutWorkPackageProperties {
  param([Parameter(Mandatory)]$WorkPackages)
  if ($WorkPackages -is [System.Collections.IDictionary]) {
    return @($WorkPackages.Keys)
  }
  return @($WorkPackages.PSObject.Properties | ForEach-Object { $_.Name })
}

function Test-WireCutEventHasProperty {
  param($Event, [string]$Name)
  if ($null -eq $Event) { return $false }
  if ($Event -is [System.Collections.IDictionary]) { return $Event.Contains($Name) }
  return $null -ne $Event.PSObject.Properties[$Name]
}

function Get-WireCutEventProperty {
  param($Event, [string]$Name)
  if ($Event -is [System.Collections.IDictionary]) { return $Event[$Name] }
  return $Event.$Name
}

function Sort-WireCutWorkPackages {
  param([Parameter(Mandatory)]$Packages)
  $sorted = [ordered]@{}
  foreach ($name in (Get-WireCutWorkPackageProperties -WorkPackages $Packages | Sort-Object)) {
    $sorted[$name] = Get-WireCutWorkPackageEntry -WorkPackages $Packages -EffectKey $name
  }
  return $sorted
}

function Copy-WireCutDispatchSnapshotObject {
  param([Parameter(Mandatory)]$Snapshot)
  $packages = [ordered]@{}
  foreach ($name in (Get-WireCutWorkPackageProperties -WorkPackages $Snapshot.work_packages)) {
    $entry = Get-WireCutWorkPackageEntry -WorkPackages $Snapshot.work_packages -EffectKey $name
    $leaseCopy = $null
    if ($null -ne $entry.lease) {
      $leaseCopy = [ordered]@{
        owner_session = [string]$entry.lease.owner_session
        attempt_id = [int]$entry.lease.attempt_id
        expires_at = [string]$entry.lease.expires_at
        effect_key = [string]$entry.lease.effect_key
      }
    }
    $evidenceCopy = $null
    if ($null -ne $entry.completion_evidence_refs) {
      $evidenceCopy = $entry.completion_evidence_refs
    }
    $pkgCopy = [ordered]@{
      status = [string]$entry.status
      attempt_id = [int]$entry.attempt_id
      effect_key = [string]$entry.effect_key
      last_transition_sequence = [int]$entry.last_transition_sequence
      lease = $leaseCopy
      completion_evidence_refs = $evidenceCopy
    }
    if ($entry.PSObject.Properties['class']) {
      $pkgCopy.class = [string]$entry.class
    }
    $packages[$name] = $pkgCopy
  }
  return [ordered]@{
    schema_version = [int]$Snapshot.schema_version
    plan_binding = [ordered]@{
      plan_commit = [string]$Snapshot.plan_binding.plan_commit
      registry_sha256 = [string]$Snapshot.plan_binding.registry_sha256
    }
    last_transition_sequence = [int]$Snapshot.last_transition_sequence
    work_packages = (Sort-WireCutWorkPackages -Packages $packages)
  }
}

function Invoke-WireCutReplayEvents {
  param(
    [Parameter(Mandatory)]$Registry,
    [Parameter(Mandatory)]$PlanBinding,
    [Parameter(Mandatory)][array]$Events
  )
  $packages = [ordered]@{}
  foreach ($wp in @($Registry.work_packages)) {
    if (-not $wp.id) { continue }
    $seed = if ($wp.PSObject.Properties['status']) { [string]$wp.status } else { 'pending' }
    $packages[$wp.id] = New-WireCutPackageRuntimeEntry -EffectKey $wp.id -SeedStatus $seed -AttemptId 1 -Sequence 0
  }
  $sequence = -1
  foreach ($event in ($Events | Sort-Object { [int]$_.sequence })) {
    $seq = [int]$event.sequence
    $type = [string]$event.type
    if ($type -eq 'sequence_init') {
      if ($seq -ne 0) { return $null }
      $sequence = 0
      continue
    }
    if ($seq -ne ($sequence + 1)) { return $null }
    $sequence = $seq
    if ($type -eq 'synthetic_register') {
      $effectKey = [string]$event.effect_key
      $class = [string]$event.class
      if (-not $packages.Contains($effectKey)) {
        $packages[$effectKey] = New-WireCutPackageRuntimeEntry -EffectKey $effectKey -SeedStatus 'pending'
        $packages[$effectKey] | Add-Member -NotePropertyName 'class' -NotePropertyValue $class -Force
        $packages[$effectKey].last_transition_sequence = $seq
      }
      continue
    }
    $effectKey = [string]$event.effect_key
    if (-not $packages.Contains($effectKey)) { return $null }
    $entry = $packages[$effectKey]
    if ($type -eq 'status_transition') {
      $entry.status = [string]$event.to_status
      $entry.attempt_id = [int]$event.attempt_id
      $entry.last_transition_sequence = $seq
      if ($event.PSObject.Properties['lease'] -and $null -ne $event.lease) {
        $entry.lease = [ordered]@{
          owner_session = [string]$event.lease.owner_session
          attempt_id = [int]$event.lease.attempt_id
          expires_at = [string]$event.lease.expires_at
          effect_key = [string]$event.lease.effect_key
        }
      } elseif ($event.PSObject.Properties['clear_lease'] -and $event.clear_lease) {
        $entry.lease = $null
      }
      if ($event.PSObject.Properties['completion_evidence_refs'] -and $null -ne $event.completion_evidence_refs) {
        $entry.completion_evidence_refs = $event.completion_evidence_refs
      }
    } elseif ($type -eq 'attempt_tombstone') {
      if ([int]$event.attempt_id -ne [int]$entry.attempt_id) { return $null }
      $entry.lease = $null
      $entry.status = 'blocked'
      $entry.last_transition_sequence = $seq
    } elseif ($type -eq 'observe_reconcile') {
      $entry.status = [string]$event.to_status
      $entry.attempt_id = [int]$event.new_attempt_id
      $entry.lease = $null
      $entry.last_transition_sequence = $seq
    }
  }
  return [ordered]@{
    schema_version = 1
    plan_binding = [ordered]@{
      plan_commit = [string]$PlanBinding.plan_commit
      registry_sha256 = [string]$PlanBinding.registry_sha256
    }
    last_transition_sequence = $sequence
    work_packages = (Sort-WireCutWorkPackages -Packages $packages)
  }
}

function Test-WireCutSnapshotMatchesEvents {
  param(
    [Parameter(Mandatory)]$Registry,
    [Parameter(Mandatory)]$Snapshot,
    [Parameter(Mandatory)][array]$Events
  )
  $binding = $Snapshot.plan_binding
  $rebuilt = Invoke-WireCutReplayEvents -Registry $Registry -PlanBinding $binding -Events $Events
  if ($null -eq $rebuilt) { return $false }
  $left = Get-WireCutCanonicalJsonSha256 -Object (Copy-WireCutDispatchSnapshotObject -Snapshot $Snapshot)
  $right = Get-WireCutCanonicalJsonSha256 -Object $rebuilt
  if ($left -ne $right -and $env:WIRE_OR_CUT_DISPATCHER_TEST -eq '1') {
    $debugDir = Join-Path ([IO.Path]::GetTempPath()) 'wirecut-dispatch-replay-debug'
    New-Item -ItemType Directory -Path $debugDir -Force | Out-Null
    Write-WireCutCanonicalJson -Path (Join-Path $debugDir 'snapshot-copy.json') -Object (Copy-WireCutDispatchSnapshotObject -Snapshot $Snapshot)
    Write-WireCutCanonicalJson -Path (Join-Path $debugDir 'snapshot-rebuilt.json') -Object $rebuilt
    Write-WireCutCanonicalJson -Path (Join-Path $debugDir 'events.json') -Object $Events
  }
  return ($left -eq $right)
}

function Test-WireCutLeaseLive {
  param($Lease)
  if ($null -eq $Lease) { return $false }
  if (-not (Test-WireCutEventHasProperty -Event $Lease -Name 'expires_at')) { return $false }
  try {
    $expiresAt = Get-WireCutEventProperty -Event $Lease -Name 'expires_at'
    $expires = if ($expiresAt -is [DateTime]) {
      [DateTime]$expiresAt
    } else {
      [DateTime]::Parse([string]$expiresAt, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::RoundtripKind)
    }
    if ($expires.Kind -eq [DateTimeKind]::Unspecified) {
      $expires = [DateTime]::SpecifyKind($expires, [DateTimeKind]::Utc)
    }
    return ($expires.ToUniversalTime() -gt [DateTime]::UtcNow)
  } catch { return $false }
}

function Get-WireCutUtcIsoNow {
  return [DateTime]::UtcNow.ToString('o')
}

function Add-WireCutDispatchEventLine {
  param(
    [Parameter(Mandatory)][string]$EventsPath,
    [Parameter(Mandatory)]$Event
  )
  $dir = Split-Path -Parent $EventsPath
  if ($dir -and -not (Test-Path -LiteralPath $dir -PathType Container)) {
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
  }
  $line = ($Event | ConvertTo-Json -Compress -Depth 20) + "`n"
  $bytes = [Text.UTF8Encoding]::new($false).GetBytes($line)
  $stream = [IO.File]::Open($EventsPath, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::Write, [IO.FileShare]::Read)
  try {
    $stream.Seek(0, [IO.SeekOrigin]::End) | Out-Null
    $stream.Write($bytes, 0, $bytes.Length)
    $stream.Flush($true)
  } finally { $stream.Dispose() }
}

function Read-WireCutDispatchEventsFromText {
  param([Parameter(Mandatory)][string]$Text)
  $events = @()
  foreach ($line in ($Text -split "`n")) {
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    $clean = $line.TrimEnd("`r")
    try { $events += ($clean | ConvertFrom-Json) } catch { return $null }
  }
  return $events
}

function Write-WireCutDispatchStateMutation {
  param(
    [Parameter(Mandatory)][string]$SnapshotPath,
    [Parameter(Mandatory)][string]$EventsPath,
    [Parameter(Mandatory)]$SnapshotObject,
    [Parameter(Mandatory)][object[]]$EventObjects
  )
  if (@($EventObjects).Count -lt 1) {
    throw 'WOC-D006 state mutation requires at least one event.'
  }
  $nextSequence = [int]$SnapshotObject.last_transition_sequence
  $touchedSequences = @{}
  foreach ($event in @($EventObjects)) {
    $nextSequence++
    $event.sequence = $nextSequence
    $event.at = Get-WireCutUtcIsoNow
    if (Test-WireCutEventHasProperty -Event $event -Name 'effect_key') {
      $effectKey = [string](Get-WireCutEventProperty -Event $event -Name 'effect_key')
      if (Test-WireCutWorkPackageExists -WorkPackages $SnapshotObject.work_packages -EffectKey $effectKey) {
        $touchedSequences[$effectKey] = $nextSequence
      }
    }
    Add-WireCutDispatchEventLine -EventsPath $EventsPath -Event $event
  }
  foreach ($effectKey in $touchedSequences.Keys) {
    $pkg = Get-WireCutWorkPackageEntry -WorkPackages $SnapshotObject.work_packages -EffectKey $effectKey
    $pkg.last_transition_sequence = [int]$touchedSequences[$effectKey]
  }
  $SnapshotObject.last_transition_sequence = $nextSequence
  $SnapshotObject.work_packages = Sort-WireCutWorkPackages -Packages $SnapshotObject.work_packages
  Write-WireCutCanonicalJson -Path $SnapshotPath -Object $SnapshotObject
  return [pscustomobject]@{ sequence = $nextSequence }
}

function Invoke-WireCutDispatchStateWrite {
  param(
    [Parameter(Mandatory)][string]$GitCommand,
    [Parameter(Mandatory)][string]$Workspace,
    [Parameter(Mandatory)][string]$SnapshotPath,
    [Parameter(Mandatory)][string]$EventsPath,
    [Parameter(Mandatory)]$SnapshotObject,
    [Parameter(Mandatory)][object[]]$EventObjects,
    [string]$CommitMessage = 'wire-or-cut dispatcher state tick'
  )
  $mutation = Write-WireCutDispatchStateMutation -SnapshotPath $SnapshotPath -EventsPath $EventsPath `
    -SnapshotObject $SnapshotObject -EventObjects $EventObjects
  $add = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'add', '--',
    ($script:WireCutDispatchStateRelative -replace '\\','/'),
    ($script:WireCutDispatchEventsRelative -replace '\\','/')
  )
  if ($add.ExitCode -ne 0) { return [pscustomobject]@{ ok = $false; reason = 'git_add_failed'; sequence = $mutation.sequence } }
  $commit = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'commit', '-m', $CommitMessage
  )
  if ($commit.ExitCode -ne 0) { return [pscustomobject]@{ ok = $false; reason = 'git_commit_failed'; sequence = $mutation.sequence } }
  $push = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'push', 'origin', "HEAD:refs/heads/$($script:WireCutDispatchStateBranch)"
  )
  if ($push.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; reason = 'push_rejected_non_ff'; sequence = $mutation.sequence; push_output = $push.Output }
  }
  return [pscustomobject]@{ ok = $true; reason = ''; sequence = $mutation.sequence }
}

function Invoke-WireCutDispatchTickPreflight {
  param(
    [Parameter(Mandatory)][string]$GitCommand,
    [Parameter(Mandatory)][string]$NodeCommand,
    [Parameter(Mandatory)][string]$Workspace,
    [ValidateSet('Initialize', 'Tick')]
    [string]$Mode
  )
  $fetchRefs = if ($Mode -eq 'Initialize') { @('main') } else { @('main', $script:WireCutDispatchStateBranch) }
  $fetchArgs = @('fetch', '--no-tags', 'origin') + $fetchRefs
  $fetch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments $fetchArgs
  if ($fetch.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D002'; message = 'Could not fetch required authority refs.' }
  }
  $head = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @('rev-parse', 'HEAD')
  $main = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @('rev-parse', $script:WireCutDispatchPlanRemoteRef)
  if ($head.ExitCode -ne 0 -or $main.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D002'; message = 'HEAD or origin/main cannot be resolved after fetch.' }
  }
  $headCommit = $head.Output.Trim()
  $originMain = $main.Output.Trim()
  if ($Mode -eq 'Initialize') {
    if ($headCommit -ne $originMain) {
      return [pscustomobject]@{ ok = $false; code = 'WOC-D003'; message = 'Initialize requires clean HEAD to equal exact origin/main.' }
    }
    $exists = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
      'ls-remote', '--exit-code', '--heads', 'origin', "refs/heads/$($script:WireCutDispatchStateBranch)"
    )
    if ($exists.ExitCode -eq 0) {
      return [pscustomobject]@{ ok = $false; code = 'WOC-D008'; message = 'Initialize is one-shot and wirecut-state already exists on origin.' }
    }
    if ($exists.ExitCode -ne 2) {
      return [pscustomobject]@{ ok = $false; code = 'WOC-D002'; message = 'Could not prove wirecut-state is absent on origin.' }
    }
    return [pscustomobject]@{ ok = $true; code = 'WOC-D000'; head_commit = $headCommit; origin_main = $originMain }
  }
  $branch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'symbolic-ref', '--quiet', '--short', 'HEAD'
  )
  $state = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'rev-parse', $script:WireCutDispatchStateRemoteRef
  )
  if ($branch.ExitCode -ne 0 -or $branch.Output.Trim() -ne $script:WireCutDispatchStateBranch -or
      $state.ExitCode -ne 0 -or $headCommit -ne $state.Output.Trim()) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D003'; message = 'Tick requires local wirecut-state to equal exact origin/wirecut-state.' }
  }
  $snapshotPath = Join-Path $Workspace $script:WireCutDispatchStateRelative
  $snapshot = Read-WireCutDispatchSnapshot -SnapshotPath $snapshotPath
  if ($null -eq $snapshot) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'Runtime-state snapshot is missing or invalid.' }
  }
  $planCommit = [string]$snapshot.plan_binding.plan_commit
  $expectedDigest = ([string]$snapshot.plan_binding.registry_sha256).ToLowerInvariant()
  $registryPath = Join-Path $Workspace $script:WireCutDispatchRegistryRelative
  if (-not (Test-Path -LiteralPath $registryPath -PathType Leaf)) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'Registry file is missing in the worktree.' }
  }
  $actualDigest = Get-WireCutCanonicalTextSha256 -Path $registryPath
  if ($planCommit -notmatch '^[0-9a-f]{40}$' -or $expectedDigest -notmatch '^[0-9a-f]{64}$' -or $actualDigest -ne $expectedDigest) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D010'; message = 'Runtime-state plan binding does not match the registry digest.' }
  }
  $commitCheck = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'cat-file', '-e', "${planCommit}^{commit}"
  )
  if ($commitCheck.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'plan_commit is not a known commit in this worktree.' }
  }
  $ancestry = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'merge-base', '--is-ancestor', $planCommit, $originMain
  )
  if ($ancestry.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'plan_commit is not an ancestor of current origin/main.' }
  }
  $mainRegistry = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'diff', '--quiet', $planCommit, $originMain, '--', ($script:WireCutDispatchRegistryRelative -replace '\\','/')
  )
  if ($mainRegistry.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'The plan registry changed on origin/main; explicit migration is required.' }
  }
  $carriedRegistry = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $Workspace -Arguments @(
    'diff', '--quiet', $planCommit, '--', ($script:WireCutDispatchRegistryRelative -replace '\\','/')
  )
  if ($carriedRegistry.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'wirecut-state carries a registry that differs from its bound plan commit.' }
  }
  $validatorPath = Join-Path $Workspace $script:WireCutDispatchValidatorRelative
  $prior = Get-Location
  try {
    Set-Location -LiteralPath $Workspace
    $ErrorActionPreference = 'Continue'
    $validatorOutput = @(& $NodeCommand $validatorPath 2>&1)
    $validatorExit = if ($null -eq $LASTEXITCODE) { 126 } else { [int]$LASTEXITCODE }
    $validatorText = ($validatorOutput | Out-String).TrimEnd()
  } finally {
    Set-Location -LiteralPath $prior
  }
  if ($validatorExit -ne 0 -or $validatorText -notmatch 'WIRE-OR-CUT VALIDATOR: coherent') {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D005'; message = 'Registry validator failed.' }
  }
  $eventsPath = Join-Path $Workspace $script:WireCutDispatchEventsRelative
  $events = Read-WireCutDispatchEvents -EventsPath $eventsPath
  if ($null -eq $events) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D009'; message = 'Event ledger is corrupt.' }
  }
  $registry = Read-WireCutDispatchRegistryAtCommit -GitCommand $GitCommand -Workspace $Workspace -Commit $planCommit
  if ($null -eq $registry) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D004'; message = 'Bound plan registry cannot be read.' }
  }
  if (-not (Test-WireCutSnapshotMatchesEvents -Registry $registry -Snapshot $snapshot -Events $events)) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D009'; message = 'Events and snapshot disagree; replay rebuild mismatch.' }
  }
  return [pscustomobject]@{
    ok = $true
    code = 'WOC-D000'
    head_commit = $headCommit
    origin_main = $originMain
    plan_commit = $planCommit
    registry = $registry
    snapshot = $snapshot
    events = $events
  }
}

function Invoke-WireCutControlWorktreeHandoff {
  param(
    [Parameter(Mandatory)][string]$GitCommand,
    [Parameter(Mandatory)][string]$ControlWorktree
  )
  $status = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
    'status', '--porcelain=v1'
  )
  if ($status.ExitCode -ne 0 -or -not [string]::IsNullOrWhiteSpace($status.Output)) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree is dirty before handoff.' }
  }
  $fetch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
    'fetch', '--no-tags', 'origin', 'main', $script:WireCutDispatchStateBranch
  )
  if ($fetch.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D002'; message = 'Control worktree fetch failed.' }
  }
  $stateRef = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
    'rev-parse', $script:WireCutDispatchStateRemoteRef
  )
  if ($stateRef.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'origin/wirecut-state is not resolvable for handoff.' }
  }
  $target = $stateRef.Output.Trim()
  $localStateBranch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
    'show-ref', '--verify', '--quiet', "refs/heads/$($script:WireCutDispatchStateBranch)"
  )
  if ($localStateBranch.ExitCode -eq 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree already has a local wirecut-state branch.' }
  }
  if ($localStateBranch.ExitCode -ne 1) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree local branch state cannot be read.' }
  }
  $checkout = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
    'checkout', '-b', $script:WireCutDispatchStateBranch, $target
  )
  if ($checkout.ExitCode -ne 0) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Could not switch control worktree to wirecut-state.' }
  }
  $head = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @('rev-parse', 'HEAD')
  if ($head.ExitCode -ne 0 -or $head.Output.Trim() -ne $target) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree HEAD does not equal exact origin/wirecut-state after handoff.' }
  }
  $clean = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
    'status', '--porcelain=v1'
  )
  if ($clean.ExitCode -ne 0 -or -not [string]::IsNullOrWhiteSpace($clean.Output)) {
    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree is dirty after handoff.' }
  }
  return [pscustomobject]@{ ok = $true; code = 'WOC-D000'; state_commit = $target }
}

