---
    [Parameter(Mandatory)][string]$PromptName,
    [Parameter(Mandatory)][string]$PromptText
  )

  $registryPath = Get-DispatchPromptRegistryPath
  if ([string]::IsNullOrWhiteSpace($registryPath)) {
    Write-DispatchEvent -EventData @{ event = 'prompt_registry_not_configured'; task = "${Product}:$Task"; prompt_name = $PromptName }
    return $true
  }
  if (-not (Test-Path -LiteralPath $registryPath -PathType Leaf)) {
    throw "Prompt registry configured but missing: $registryPath"
  }
  if (-not (Test-Path -LiteralPath $script:PromptRegistryScript -PathType Leaf)) {
    throw "Prompt registry script missing: $($script:PromptRegistryScript)"
  }

  $tempPrompt = Join-Path $env:TEMP ("dispatch-prompt-registry-{0}-{1}.txt" -f ($PromptName -replace '[^A-Za-z0-9._-]', '_'), [guid]::NewGuid().ToString('N'))
  try {
    # Windows PowerShell 5.1's `-Encoding utf8` prepends a BOM, producing a different registry
    # hash than PowerShell 7 for identical text. Write explicit UTF-8 without BOM on both hosts.
    [IO.File]::WriteAllText($tempPrompt, $PromptText + "`r`n", [Text.UTF8Encoding]::new($false))
    $out = & (Resolve-DispatchPwshExe) -NoProfile -ExecutionPolicy Bypass -File $script:PromptRegistryScript Check -RegistryPath $registryPath -Name $PromptName -PromptFile $tempPrompt 2>&1 | Out-String
    $code = $LASTEXITCODE
    if ($code -eq 0) {
      Write-DispatchEvent -EventData @{ event = 'prompt_registry_check_pass'; task = "${Product}:$Task"; prompt_name = $PromptName; registry = $registryPath }
      return $true
    }
    throw "Prompt registry check failed for $PromptName (exit $code): $($out.Trim())"
  }
  finally {
    Remove-Item -LiteralPath $tempPrompt -Force -ErrorAction SilentlyContinue
  }
}

