2	
3	import { useState } from 'react';
4	
5	type Props = {
6	  workspaceId: string;
7	  outcomeId: string;
8	  valueProof: Record<string, unknown> | null;
9	  twin: Record<string, unknown> | null;
10	  onRefresh: () => void;
11	};
12	
13	type BusyState =
14	  | { kind: 'accept' }
15	  | { kind: 'dispute' }
16	  | { kind: 'resolve'; disputeId: string }
17	  | null;
18	
19	export function ValueProofPanel({ workspaceId, outcomeId, valueProof, twin, onRefresh }: Props) {
20	  const drift = (twin?.drift ?? null) as Record<string, unknown> | null;
21	  const grade = valueProof?.grade as string | undefined;
22	  const blockers = (valueProof?.billingBlockers as string[] | undefined) ?? [];
23	  const lineage = (valueProof?.lineage as string[] | undefined) ?? [];
24	  const disputes = (valueProof?.disputes as Array<Record<string, unknown>> | undefined) ?? [];
25	
26	  const [busy, setBusy] = useState<BusyState>(null);
27	  const [actionError, setActionError] = useState<string | null>(null);
28	  const [disputeReason, setDisputeReason] = useState('');
29	  const [resolutionNotes, setResolutionNotes] = useState<Record<string, string>>({});
30	
31	  // The mutation routes are scoped to an outcome; without one there is nothing
32	  // to accept, dispute, or resolve, so the action controls stay hidden.
33	  const canMutate = outcomeId.length > 0;
34	  const outcomeBase = canMutate
35	    ? `/api/v2/workspaces/${encodeURIComponent(workspaceId)}/value-proof/outcomes/${encodeURIComponent(outcomeId)}`
36	    : '';
37	
38	  // Single POST path for all three mutations: optimistic refresh on success,
39	  // surface the server's error code (auth/policy/store) on failure. Auth is
40	  // enforced server-side via the session cookie sent with the same-origin
41	  // fetch; a forbidden action returns its code here as the error state.
42	  async function runMutation(
43	    busyState: BusyState,
44	    url: string,
45	    body: Record<string, unknown>,
46	  ): Promise<boolean> {
47	    setBusy(busyState);
48	    setActionError(null);
49	    try {
50	      const res = await fetch(url, {
51	        method: 'POST',
52	        headers: { 'Content-Type': 'application/json' },
53	        body: JSON.stringify(body),
54	      });
55	      const json = (await res.json().catch(() => ({}))) as { error?: string };
56	      if (!res.ok) {
57	        setActionError(json.error ?? 'mutation_failed');
58	        return false;
59	      }
60	      onRefresh();
61	      return true;
62	    } catch {
63	      setActionError('mutation_failed');
64	      return false;
65	    } finally {
66	      setBusy(null);
67	    }
68	  }
69	
70	  function handleAccept() {
71	    if (!outcomeBase) return;
72	    void runMutation({ kind: 'accept' }, `${outcomeBase}/acceptance`, {});
73	  }
74	
75	  async function handleDispute() {
76	    if (!outcomeBase) return;
77	    const reason = disputeReason.trim();
78	    if (!reason) {
79	      setActionError('dispute_reason_required');
80	      return;
81	    }
82	    const ok = await runMutation({ kind: 'dispute' }, `${outcomeBase}/disputes`, { reason });
83	    if (ok) setDisputeReason('');
84	  }
85	
86	  async function handleResolve(disputeId: string) {
87	    if (!outcomeBase) return;
88	    const resolutionNote = (resolutionNotes[disputeId] ?? '').trim();
89	    if (!resolutionNote) {
90	      setActionError('resolution_note_required');
91	      return;
92	    }
93	    const ok = await runMutation(
94	      { kind: 'resolve', disputeId },
95	      `${outcomeBase}/disputes/${encodeURIComponent(disputeId)}/resolution`,
96	      { resolutionNote },
