'use client';

import { useState } from 'react';

type Props = {
  workspaceId: string;
  outcomeId: string;
  valueProof: Record<string, unknown> | null;
  twin: Record<string, unknown> | null;
  onRefresh: () => void;
};

type BusyState =
  | { kind: 'accept' }
  | { kind: 'dispute' }
  | { kind: 'resolve'; disputeId: string }
  | null;

export function ValueProofPanel({ workspaceId, outcomeId, valueProof, twin, onRefresh }: Props) {
  const drift = (twin?.drift ?? null) as Record<string, unknown> | null;
  const grade = valueProof?.grade as string | undefined;
  const blockers = (valueProof?.billingBlockers as string[] | undefined) ?? [];
  const lineage = (valueProof?.lineage as string[] | undefined) ?? [];
  const disputes = (valueProof?.disputes as Array<Record<string, unknown>> | undefined) ?? [];

  const [busy, setBusy] = useState<BusyState>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [disputeReason, setDisputeReason] = useState('');
  const [resolutionNotes, setResolutionNotes] = useState<Record<string, string>>({});

  // The mutation routes are scoped to an outcome; without one there is nothing
  // to accept, dispute, or resolve, so the action controls stay hidden.
  const canMutate = outcomeId.length > 0;
  const outcomeBase = canMutate
    ? `/api/v2/workspaces/${encodeURIComponent(workspaceId)}/value-proof/outcomes/${encodeURIComponent(outcomeId)}`
    : '';

  // Single POST path for all three mutations: optimistic refresh on success,
  // surface the server's error code (auth/policy/store) on failure. Auth is
  // enforced server-side via the session cookie sent with the same-origin
  // fetch; a forbidden action returns its code here as the error state.
  async function runMutation(
    busyState: BusyState,
    url: string,
    body: Record<string, unknown>,
  ): Promise<boolean> {
    setBusy(busyState);
    setActionError(null);
    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const json = (await res.json().catch(() => ({}))) as { error?: string };
      if (!res.ok) {
        setActionError(json.error ?? 'mutation_failed');
        return false;
      }
      onRefresh();
      return true;
    } catch {
      setActionError('mutation_failed');
      return false;
    } finally {
      setBusy(null);
    }
  }

  function handleAccept() {
    if (!outcomeBase) return;
    void runMutation({ kind: 'accept' }, `${outcomeBase}/acceptance`, {});
  }

  async function handleDispute() {
    if (!outcomeBase) return;
    const reason = disputeReason.trim();
    if (!reason) {
      setActionError('dispute_reason_required');
      return;
    }
    const ok = await runMutation({ kind: 'dispute' }, `${outcomeBase}/disputes`, { reason });
    if (ok) setDisputeReason('');
  }

  async function handleResolve(disputeId: string) {
    if (!outcomeBase) return;
    const resolutionNote = (resolutionNotes[disputeId] ?? '').trim();
    if (!resolutionNote) {
      setActionError('resolution_note_required');
      return;
    }
    const ok = await runMutation(
      { kind: 'resolve', disputeId },
      `${outcomeBase}/disputes/${encodeURIComponent(disputeId)}/resolution`,
      { resolutionNote },
    );
    if (ok) {
      setResolutionNotes((prev) => {
        if (!(disputeId in prev)) return prev;
        const next = { ...prev };
        delete next[disputeId];
        return next;
      });
    }
  }

  const accepting = busy?.kind === 'accept';
  const disputing = busy?.kind === 'dispute';

  return (
    <section className="mt-8 space-y-6">
      <div className="flex items-center justify-between gap-4">
        <h2 className="text-lg font-medium text-zinc-900">Live read model</h2>
        <button
          type="button"
          onClick={onRefresh}
          className="rounded border border-zinc-300 px-3 py-1.5 text-sm text-zinc-800 hover:bg-zinc-50"
        >
          Refresh
        </button>
      </div>

      {actionError ? <p className="text-sm text-red-700">Action failed: {actionError}</p> : null}

      <div className="grid gap-4 md:grid-cols-2">
        <div className="border-t border-zinc-200 pt-4">
          <h3 className="text-sm font-medium uppercase tracking-wide text-zinc-500">
            Process drift
          </h3>
          <p className="mt-2 text-2xl font-semibold text-zinc-900">
            {String(drift?.severity ?? '—')}
          </p>
          <p className="mt-1 text-sm text-zinc-600">
            Evidence coverage:{' '}
            {drift?.evidenceCoverage != null
              ? `${Math.round(Number(drift.evidenceCoverage) * 100)}%`
              : '—'}
          </p>
          {Array.isArray(drift?.notes) && drift.notes.length > 0 ? (
            <ul className="mt-2 list-disc pl-5 text-sm text-zinc-700">
              {(drift.notes as string[]).map((n) => (
                <li key={n}>{n}</li>
              ))}
            </ul>
          ) : null}
        </div>

        <div className="border-t border-zinc-200 pt-4">
          <h3 className="text-sm font-medium uppercase tracking-wide text-zinc-500">
            Outcome grade
          </h3>
          <p className="mt-2 text-2xl font-semibold text-zinc-900">{grade ?? '—'}</p>
          <p className="mt-1 text-sm text-zinc-600">
            Attribution: {String(valueProof?.attributionStrength ?? '—')}
          </p>
          <p className="mt-1 text-sm text-zinc-600">
            Billing eligible: {valueProof?.billingEligible === true ? 'yes' : 'no'}
          </p>
          {blockers.length > 0 ? (
            <ul className="mt-2 list-disc pl-5 text-sm text-amber-800">
              {blockers.map((b) => (
                <li key={b}>{b}</li>
              ))}
            </ul>
          ) : null}
          {canMutate ? (
            <div className="mt-3">
              <button
                type="button"
                onClick={handleAccept}
                disabled={busy !== null}
                className="rounded border border-zinc-300 px-3 py-1.5 text-sm text-zinc-800 hover:bg-zinc-50 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {accepting ? 'Accepting…' : 'Accept outcome'}
              </button>
            </div>
          ) : null}
        </div>
      </div>

      <div className="border-t border-zinc-200 pt-4">
        <h3 className="text-sm font-medium uppercase tracking-wide text-zinc-500">
          Open disputes
        </h3>
        {disputes.filter((d) => d.status === 'open').length === 0 ? (
          <p className="mt-2 text-sm text-zinc-600">None</p>
        ) : (
          <ul className="mt-2 space-y-2 text-sm text-zinc-800">
            {disputes
              .filter((d) => d.status === 'open')
              .map((d) => {
                const disputeId = String(d.disputeId);
                const resolving =
                  busy !== null && busy.kind === 'resolve' && busy.disputeId === disputeId;
                return (
                  <li key={disputeId} className="space-y-1">
                    <div>
                      {String(d.reason)} <span className="text-zinc-500">({disputeId})</span>
                    </div>
                    {canMutate ? (
                      <div className="flex flex-wrap items-center gap-2">
                        <input
                          type="text"
                          aria-label={`Resolution note for dispute ${disputeId}`}
                          value={resolutionNotes[disputeId] ?? ''}
                          onChange={(e) =>
                            setResolutionNotes((prev) => ({ ...prev, [disputeId]: e.target.value }))
                          }
                          placeholder="Resolution note (required)"
                          className="min-w-[12rem] flex-1 rounded border border-zinc-300 px-2 py-1 text-sm"
                        />
                        <button
                          type="button"
                          onClick={() => void handleResolve(disputeId)}
                          disabled={busy !== null}
                          className="rounded border border-zinc-300 px-2.5 py-1 text-sm text-zinc-800 hover:bg-zinc-50 disabled:cursor-not-allowed disabled:opacity-50"
                        >
                          {resolving ? 'Resolving…' : 'Resolve'}
                        </button>
                      </div>
                    ) : null}
                  </li>
                );
              })}
          </ul>
        )}

        {canMutate ? (
          <div className="mt-3 flex flex-wrap items-center gap-2">
            <input
              type="text"
              aria-label="Reason for dispute"
              value={disputeReason}
              onChange={(e) => setDisputeReason(e.target.value)}
              placeholder="Reason for dispute (required)"
              className="min-w-[12rem] flex-1 rounded border border-zinc-300 px-2 py-1 text-sm"
            />
            <button
              type="button"
              onClick={() => void handleDispute()}
              disabled={busy !== null}
              className="rounded border border-zinc-300 px-3 py-1.5 text-sm text-zinc-800 hover:bg-zinc-50 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {disputing ? 'Raising…' : 'Raise dispute'}
            </button>
          </div>
        ) : null}
      </div>

      <div className="border-t border-zinc-200 pt-4">
        <h3 className="text-sm font-medium uppercase tracking-wide text-zinc-500">Lineage</h3>
        {lineage.length === 0 ? (
          <p className="mt-2 text-sm text-zinc-600">No immutable inputs linked yet.</p>
        ) : (
          <ul className="mt-2 list-disc pl-5 font-mono text-xs text-zinc-700">
            {lineage.map((l) => (
              <li key={l}>{l}</li>
            ))}
          </ul>
        )}
      </div>
    </section>
  );
}

