const [busy, setBusy] = useState<BusyState>(null);
const [actionError, setActionError] = useState<string | null>(null);
const [disputeReason, setDisputeReason] = useState('');
const [resolutionNotes, setResolutionNotes] = useState<Record<string, string>>({});

// Idempotency: one commandId per logical action, held until that action
// SUCCEEDS — a retry after a dropped response reuses the same id, so the
// server dedupes instead of creating a duplicate dispute/acceptance.
const commandIdsRef = useRef<Record<string, string>>({});
function commandIdFor(actionKey: string): string {
  const existing = commandIdsRef.current[actionKey];
  if (existing) return existing;
  const fresh = crypto.randomUUID();
  commandIdsRef.current[actionKey] = fresh;
  return fresh;
}

// The mutation routes are scoped to a workspace + outcome; without BOTH ids
// there is no valid target URL, so the action controls stay hidden.
const canMutate = workspaceId.length > 0 && outcomeId.length > 0;
const outcomeBase = canMutate
  ? `/api/v2/workspaces/${encodeURIComponent(workspaceId)}/value-proof/outcomes/${encodeURIComponent(outcomeId)}`
  : '';

// Single POST path for all three mutations: refresh completes BEFORE the
// busy state clears, so controls re-enable against fresh data. Auth is
// enforced server-side via the session cookie sent with the same-origin
// fetch; a forbidden action returns its code here as the error state.
async function runMutation(
  busyState: BusyState,
  actionKey: string,
  url: string,
  body: Record<string, unknown>,
): Promise<boolean> {
  setBusy(busyState);
  setActionError(null);
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...body, commandId: commandIdFor(actionKey) }),
    });
    const json = (await res.json().catch(() => ({}))) as { error?: string };
    if (!res.ok) {
      setActionError(json.error ?? 'mutation_failed');
      return false;
    }
    delete commandIdsRef.current[actionKey];
    await onRefresh();
    return true;
  } catch {
    setActionError('mutation_failed');
    return false;
  } finally {
    setBusy(null);
  }
}

function handleAccept() {
  if (!outcomeBase) return;
  void runMutation({ kind: 'accept' }, 'accept', `${outcomeBase}/acceptance`, {});
}

async function handleDispute() {
  if (!outcomeBase) return;
  const reason = disputeReason.trim();
  if (!reason) {
    setActionError('dispute_reason_required');
    return;
  }
  const ok = await runMutation({ kind: 'dispute' }, 'dispute', `${outcomeBase}/disputes`, {
    reason,
  });
  if (ok) setDisputeReason('');
}

async function handleResolve(disputeId: string) {
  if (!outcomeBase) return;
  const resolutionNote = (resolutionNotes[disputeId] ?? '').trim();
  if (!resolutionNote) {
    setActionError('resolution_note_required');
    return;
  }
  const ok = await runMutation(
    { kind: 'resolve', disputeId },
    `resolve:${disputeId}`,
    `${outcomeBase}/disputes/${encodeURIComponent(disputeId)}/resolution`,
    { resolutionNote },
  );

