function normalizeUrl(value) {
  if (!value) return '';
  return value.trim().replace(/\/+$/, '');
}

function buildUrl(baseUrl, pathname) {
  const cleanPath = pathname.startsWith('/') ? pathname : `/${pathname}`;
  return `${normalizeUrl(baseUrl)}${cleanPath}`;
}

export function getProductionConfig() {
  return productionConfig;
}

export function resolveCanonicalProductionBaseUrl(env = process.env) {
  return normalizeUrl(
    env.AT_CANONICAL_PROD_BASE_URL ??
      env.AT_PRODUCTION_BASE_URL ??
      env.MISSION15_PROD_BASE_URL ??
      productionConfig.canonicalBaseUrl,
  );
}

export function resolveProductionAliasUrls(env = process.env) {
  const urls = [
    resolveCanonicalProductionBaseUrl(env),
    ...productionConfig.aliasUrls.map((value) => normalizeUrl(value)),
  ].filter(Boolean);
  return [...new Set(urls)];
}

export function resolveProductionUrls(env = process.env) {
  const baseUrl = resolveCanonicalProductionBaseUrl(env);
  return {
    baseUrl,
    aliasUrls: resolveProductionAliasUrls(env),
    healthUrl: buildUrl(baseUrl, productionConfig.routes.health),
    liveUrl: buildUrl(baseUrl, productionConfig.routes.live),
    legacyLiveDemoUrl: buildUrl(baseUrl, productionConfig.routes.liveDemoLegacy),
    ingestionEvidenceUrl: buildUrl(baseUrl, productionConfig.routes.ingestionEvidence),
    routes: { ...productionConfig.routes },
    vercel: { ...productionConfig.vercel },
  };
}

export function resolveMission12IngestionUrl(env = process.env) {
  return normalizeUrl(env.MISSION12_INGESTION_URL ?? resolveProductionUrls(env).ingestionEvidenceUrl);
}

export function resolveVercelScope(env = process.env) {
  return env.VERCEL_SCOPE?.trim() || productionConfig.vercel.scope;
}

