/**
 * Strategy — the single strategy console (/strategy), merged from the former
 * Cockpit + Pod mega-consoles.
 *
 * Three tabs wired to engine /api/dse/* endpoints:
 *   1. Strategy  — strategy lifecycle (UNKNOWN→ACTIVE front door) + state
 *                  mutations via api.setStrategyState. The default tab.
 *   2. Approvals — "Recent decisions" (APPROVED + REJECTED plans, read-only).
 *   3. Risk      — circuit breaker via api.circuitBreaker().
 *
 * Dropped vs the old Pod page:
 *   - Positions  — overlaps /paper.
 *   - Trade Plans — folded into the /research feed.
 *   - Knowledge  — no backend endpoint.
 *
 * Top KPI strip: regime, breaker state, active strategies, shadow signals.
 *
 * Honest framing: nothing here is live-tradeable. Strategies are in shadow
 * mode; the lifecycle ledger is the human-in-the-loop front door, not a
 * money-making system, and no edge is claimed.
 */

import { useEffect, useRef, useState } from "react";
import { api, ApiError } from "../api/client";
import type {
  EngineTradePlan,
  CircuitBreakerResponse,
  StrategyLifecycleRow,
  RegimeResponse,
  StrategyLedgerSetRequest,
  PromotionReport,
} from "../api/types";
import { KpiCard } from "../components/ui/KpiCard";
import { DataTable } from "../components/ui/DataTable";
