function StrategyTab() {
  const { addToast } = useAppStore();
  const [rows, setRows] = useState<StrategyLifecycleRow[]>([]);
  const [asOfUtc, setAsOfUtc] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionModal, setActionModal] = useState<{
    row: StrategyLifecycleRow;
    targetState: "ACTIVE" | "PAUSED" | "RETIRED";
  } | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const load = async () => {
    try {
      const data = await api.strategyLifecycle();
      setRows(data.strategies);
      setAsOfUtc(data.as_of_utc);
      setError(null);
    } catch (e) {
      setError(
        e instanceof Error ? e.message : "Failed to load strategy lifecycle",
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    const id = setInterval(load, 30_000);
    return () => clearInterval(id);
  }, []);

  const handleStateChange = async (reason: string) => {
    if (!actionModal) return;
    setSubmitting(true);
    const req: StrategyLedgerSetRequest = {
      strategy_family: actionModal.row.strategy_family,
      state: actionModal.targetState,
      reason,
      set_by: "ui",
    };
    try {
      await api.setStrategyState(req);
      addToast({
        title: "Strategy updated",
        body: `${humanizeStrategy(req.strategy_family)} → ${humanizeStrategyState(req.state)}`,
        tone: "ok",
      });
      setActionModal(null);
      await load();
    } catch (e) {
      addToast({
        title: "Update failed",
        body: e instanceof Error ? e.message : "Unknown error",
        tone: "bad",
      });
    } finally {
      setSubmitting(false);
    }
  };

  const columns = [
    {
      key: "family",
      header: "Strategy",
      cell: (r: StrategyLifecycleRow) => (
        <span
          className="ticker-cell"
          data-tooltip={`raw value: ${r.strategy_family}`}
        >
          {humanizeStrategy(r.strategy_family)}
        </span>
      ),
    },
