  const [rows, setRows] = useState<StrategyLifecycleRow[]>([]);
  const [asOfUtc, setAsOfUtc] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  // Per-family stage-3 promotion reports (WC-207 read-path wiring of
  // GET /api/dse/promotion/{family}). undefined = still loading, null =
  // report unavailable for that family (honest dash, never fake data).
  const [promotion, setPromotion] = useState<
    Record<string, PromotionReport | null>
  >({});
  const [actionModal, setActionModal] = useState<{
    row: StrategyLifecycleRow;
    targetState: "ACTIVE" | "PAUSED" | "RETIRED";
  } | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const load = async () => {
    try {
      const data = await api.strategyLifecycle();
      setRows(data.strategies);
      setAsOfUtc(data.as_of_utc);
      setError(null);
      const families = Array.from(
        new Set(data.strategies.map((r) => r.strategy_family)),
      );
      const reports = await Promise.all(
        families.map((f) => api.promotionReport(f).catch(() => null)),
      );
      const next: Record<string, PromotionReport | null> = {};
      families.forEach((f, i) => {
        next[f] = reports[i];
      });
      setPromotion(next);
    } catch (e) {
      setError(
        e instanceof Error ? e.message : "Failed to load strategy lifecycle",
      );
    } finally {
      setLoading(false);
    }
  };

