/**
 * DataOperatorToken.test.tsx
 *
 * Tests for the Operator access row added to DataPage:
 *   - Renders with the expected descriptive copy.
 *   - "Set token" writes the value to localStorage.dse_operator_token.
 *   - "Clear" removes the key from localStorage.
 *   - No behavior change for public visitors (key absent → no side-effects).
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';

// ── API mocks (DataPage pulls in SourceTable + GuardrailStrip which call API) ──

const { apiStubs, researchStubs } = vi.hoisted(() => ({
  apiStubs: {
    sourceHealth: vi.fn<() => Promise<unknown[]>>().mockResolvedValue([]),
    regime: vi.fn<() => Promise<unknown>>().mockResolvedValue(null),
    circuitBreaker: vi.fn<() => Promise<unknown>>().mockResolvedValue(null),
    strategyLifecycle: vi.fn<() => Promise<unknown>>().mockResolvedValue(null),
  },
  researchStubs: {
    collectors: vi.fn<() => Promise<unknown>>().mockResolvedValue({
      available: false,
      l1_count: 0,
      l2_count: 0,
      l1_last: null,
      l2_last: null,
      as_of_utc: null,
    }),
  },
}));

vi.mock('../../api/client', () => ({ api: apiStubs }));
vi.mock('../../api/infoEngine', () => ({ research: researchStubs }));

import { DataPage } from '../Data';

const LS_KEY = 'dse_operator_token';

describe('DataPage — Operator access row', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
  });

  afterEach(() => {
    localStorage.clear();
  });

  it('renders the "Operator access" section heading', async () => {
    render(<DataPage />);
    await waitFor(() => {
      expect(screen.getByText(/operator access/i)).toBeTruthy();
    });
  });

  it('renders the public-view read-only copy', async () => {
    render(<DataPage />);
    await waitFor(() => {
      expect(
        screen.getByText(
          /public view is read-only\. operators paste their token here to enable actions\./i,
        ),
      ).toBeTruthy();
    });
  });

  it('renders a password-type input', async () => {
    render(<DataPage />);
    await waitFor(() => {
      const input = screen.getByTestId('operator-token-input');
      expect(input).toBeTruthy();
      expect((input as HTMLInputElement).type).toBe('password');
    });
  });

  it('writes token to localStorage when "Set token" is clicked', async () => {
    render(<DataPage />);
    await waitFor(() => {
      expect(screen.getByTestId('operator-token-input')).toBeTruthy();
    });

    const input = screen.getByTestId('operator-token-input') as HTMLInputElement;
    fireEvent.change(input, { target: { value: 'my-secret-token' } });
    fireEvent.click(screen.getByTestId('operator-token-set'));

    expect(localStorage.getItem(LS_KEY)).toBe('my-secret-token');
  });

  it('removes token from localStorage when "Clear" is clicked', async () => {
    localStorage.setItem(LS_KEY, 'existing-token');

    render(<DataPage />);
    await waitFor(() => {
      expect(screen.getByTestId('operator-token-clear')).toBeTruthy();
    });

    fireEvent.click(screen.getByTestId('operator-token-clear'));
    expect(localStorage.getItem(LS_KEY)).toBeNull();
  });

  it('does not write anything to localStorage if the input is empty and Set is clicked', async () => {
    render(<DataPage />);
    await waitFor(() => {
      expect(screen.getByTestId('operator-token-set')).toBeTruthy();
    });

    // Input is empty by default — clicking Set should remove any stale key
    localStorage.setItem(LS_KEY, 'stale');
    fireEvent.click(screen.getByTestId('operator-token-set'));
    // Empty string → key is removed
    expect(localStorage.getItem(LS_KEY)).toBeNull();
  });

  it('public visitors see the section but localStorage is unaffected by default', async () => {
    render(<DataPage />);
    await waitFor(() => {
      expect(screen.getByTestId('operator-access-row')).toBeTruthy();
    });
    // No interaction → key stays absent
    expect(localStorage.getItem(LS_KEY)).toBeNull();
  });
});

