toolUseResult.originalFile:
/**
 * NBR SRO listing fetcher + parser.
 *
 * Downloads the official National Board of Revenue (NBR) SRO listing page
 * (https://nbr.gov.bd/regulations/sros/income-tax-sros/eng) and parses its
 * rows into SRO entries: title (SRO number as printed), date, description,
 * and PDF link. Entries are convertible into the EXISTING gazette register
 * format (`GazetteRegisterEntry`) that scripts/run-gazette-register.ts and
 * the register-diff pipeline consume.
 *
 * Outbound guardrails mirror gazette-register-pipeline.fetchGazetteEntry:
 *   - https only, host allowlist (nbr.gov.bd / www.nbr.gov.bd)
 *   - repo SSRF guard (`@/lib/security/ssrf-guard` safeFetch) by default
 *   - fetch timeout, content-type check, body size caps
 *
 * The listing page renders its rows client-side from a server-embedded
 * <tbody> (bootstrap-table), so one HTTP fetch yields the newest ~40 SROs —
 * more than enough for a daily monitor cadence. Older pages are not fetched.
 *
 * The parser is regex-based against the stable NBR table template
 * (Sl. | SRO No. | Date | Description | Amended by | Download) and is
 * pinned by a real listing snapshot fixture test.
 */

import { createHash } from "node:crypto";
import { safeFetch } from "@/lib/security/ssrf-guard";
import type { GazetteRegisterEntry } from "./gazette-register-pipeline";

export const DEFAULT_NBR_SRO_LISTING_URL =
  "https://nbr.gov.bd/regulations/sros/income-tax-sros/eng";

const MIN_LISTING_BYTES = 500;
const MAX_LISTING_BYTES = 5 * 1024 * 1024;
const DEFAULT_TIMEOUT_MS = 20_000;

export interface SroListingEntry {
  /** SRO number exactly as printed, e.g. "S.R.O No 213-Ain/Aykor-4/2026" (may be Bangla) */
  sroNumber: string;
  /** Normalized dedupe key — the same SRO edition always yields the same key */
  editionKey: string;
  /** Date exactly as printed on the listing, dd/mm/yyyy */
  publishedDate: string;
  /** publishedDate converted to ISO yyyy-mm-dd */
  publishedIso: string;
  /** Description column text */
  description: string;
  /** Absolute URL of the SRO PDF on nbr.gov.bd */
  pdfUrl: string;
}

function sha256Hex(input: string): string {
  return createHash("sha256").update(input).digest("hex");
}

function isNbrHost(host: string): boolean {
  const normalized = host.toLowerCase();
  return normalized === "nbr.gov.bd" || normalized === "www.nbr.gov.bd";
}

function decodeHtmlEntities(text: string): string {
  return text
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'");
}

function stripTags(html: string): string {
  return decodeHtmlEntities(html.replace(/<[^>]*>/g, " "))
    .replace(/\s+/g, " ")
    .trim();
}

/** Normalize an SRO number string into a stable edition/dedupe key. */
export function normalizeSroEditionKey(sroNumber: string): string {
  return sroNumber.normalize("NFC").replace(/\s+/g, " ").trim().toLowerCase();
}

function parsePrintedDate(printed: string): { publishedDate: string; publishedIso: string } | null {
  const match = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(printed.trim());
  if (!match) return null;
  const [, dd, mm, yyyy] = match;
  const day = Number(dd);
  const month = Number(mm);
  if (month < 1 || month > 12 || day < 1 || day > 31) return null;
  return { publishedDate: `${dd}/${mm}/${yyyy}`, publishedIso: `${yyyy}-${mm}-${dd}` };
}

/**
 * Parse the NBR SRO listing HTML into SRO entries.
 *
 * Rows that lack a PDF link, a non-empty SRO title, or a valid dd/mm/yyyy
 * date are skipped. Duplicate editions within one page keep the first row.
 * Returns entries in listing order (newest first on the live site).
 */
export function parseSroListingEntries(html: string, listingUrl: string): SroListingEntry[] {
  const entries: SroListingEntry[] = [];
  const seenKeys = new Set<string>();

  const rowPattern = /<tr[^>]*data-index="?\d+"?[^>]*>([\s\S]*?)<\/tr>/gi;
  let rowMatch: RegExpExecArray | null;
  while ((rowMatch = rowPattern.exec(html)) !== null) {
    const rowHtml = rowMatch[1];

    const cells: string[] = [];
    const cellPattern = /<td[^>]*>([\s\S]*?)<\/td>/gi;
    let cellMatch: RegExpExecArray | null;
    while ((cellMatch = cellPattern.exec(rowHtml)) !== null) {
      cells.push(cellMatch[1]);
    }
    // Template columns: Sl. | SRO No. | Date | Description | Amended by | Download
    if (cells.length < 4) continue;

    const anchorMatch = /<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/i.exec(cells[1]);
    if (!anchorMatch) continue;
    const [, href, anchorHtml] = anchorMatch;

    const sroNumber = stripTags(anchorHtml);
    if (!sroNumber) continue;

    const printedDate = stripTags(cells[2]);
    const parsedDate = parsePrintedDate(printedDate);
    if (!parsedDate) continue;

    let pdfUrl: string;
    try {
      pdfUrl = new URL(decodeHtmlEntities(href.trim()), listingUrl).toString();
    } catch {
      continue;
    }
    const parsedPdf = new URL(pdfUrl);
    if (parsedPdf.protocol !== "https:" || !isNbrHost(parsedPdf.host)) continue;

    const editionKey = normalizeSroEditionKey(sroNumber);
    if (seenKeys.has(editionKey)) continue;
    seenKeys.add(editionKey);

    entries.push({
      sroNumber,
      editionKey,
      publishedDate: parsedDate.publishedDate,
      publishedIso: parsedDate.publishedIso,
      description: stripTags(cells[3]),
      pdfUrl,
    });
  }

  return entries;
}

/**
 * Map a parsed SRO listing entry into the existing gazette register format.
 *
 * The monitor downloads the listing only — PDF bytes are not fetched — so
 * `byteLength` is 0 and `sourceSha256` is a deterministic hash of the edition
 * metadata (edition key + printed date + PDF URL). `issueKey` mirrors the
 * register pipeline's buildIssueKey(url, sha) recipe, so the same SRO edition
 * always produces the same register identity (register-diff idempotency).
 */
export function sroEntryToRegisterEntry(
  entry: SroListingEntry,
  fetchedAt: string
): GazetteRegisterEntry {
  const sourceSha256 = sha256Hex(
    `nbr-sro-listing::${entry.editionKey}::${entry.publishedDate}::${entry.pdfUrl}`
  );
  return {
    issueKey: sha256Hex(`${entry.pdfUrl}::${sourceSha256}`),
    sourceUrl: entry.pdfUrl,
    sourceLabel: entry.sroNumber,
    sourceHost: new URL(entry.pdfUrl).host,
    sourceIssueId: entry.sroNumber,
    contentType: "application/pdf",
    byteLength: 0,
    sourceSha256,
    fetchedAt,
  };
}

async function defaultFetch(sourceUrl: string, init?: RequestInit): Promise<Response> {
  return safeFetch(sourceUrl, init);
}

/**
 * Download the NBR SRO listing page HTML.
 *
 * Throws on any failure (non-https, disallowed host, HTTP error, non-HTML
 * content type, body outside size caps, timeout) — callers must treat a
 * throw as a failed run, never as an empty listing.
 */
export async function fetchNbrSroListing(options: {
  listingUrl?: string;
  fetchImpl?: typeof fetch;
  timeoutMs?: number;
} = {}): Promise<{ html: string; listingUrl: string }> {
  const listingUrl = options.listingUrl ?? DEFAULT_NBR_SRO_LISTING_URL;
  const fetchImpl = options.fetchImpl ?? (defaultFetch as typeof fetch);
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;

  const parsedUrl = new URL(listingUrl);
  if (parsedUrl.protocol !== "https:") {
    throw new Error("NBR SRO listing URL must use https");
  }
  if (!isNbrHost(parsedUrl.host)) {
    throw new Error("NBR SRO listing host must be nbr.gov.bd or www.nbr.gov.bd");
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  let response: Response;
  try {
    response = await fetchImpl(listingUrl, {
      method: "GET",
      redirect: "follow",
      signal: controller.signal,
      headers: {
        "user-agent": "Talent/1.0 gazette-sro-monitor",
        accept: "text/html,application/xhtml+xml,*/*;q=0.8",
      },
    });
  } finally {
    clearTimeout(timeout);
  }

  if (!response.ok) {
    throw new Error(`NBR SRO listing returned HTTP ${response.status}`);
  }

  const contentType = (response.headers.get("content-type") ?? "").toLowerCase();
  if (contentType && !contentType.includes("text/html") && !contentType.includes("application/xhtml")) {
    throw new Error(`NBR SRO listing returned non-HTML content type: ${contentType}`);
  }

  const bytes = Buffer.from(await response.arrayBuffer());
  if (bytes.byteLength < MIN_LISTING_BYTES) {
    throw new Error(`NBR SRO listing body too small (${bytes.byteLength} bytes)`);
  }
  if (bytes.byteLength > MAX_LISTING_BYTES) {
    throw new Error(`NBR SRO listing body too large (${bytes.byteLength} bytes)`);
  }

  return { html: bytes.toString("utf8"), listingUrl };
}

