import type { Migration } from "./types";
import { execSqlScript } from "./helpers";

// 045: NBR SRO gazette monitor (WC-209). State for the real nbr.gov.bd SRO
// listing fetch wired into the gazette-monitor cron.
//
// gazette_sro_editions: one row per (tenant, SRO edition key) seen on the NBR
// listing. UNIQUE(tenant_id, edition_key) is the DB-level idempotency
// backstop — the same SRO edition can never be proposed twice.
//
// gazette_monitor_runs: one row per cron run per tenant. Fetch/parse failures
// are persisted as status='failed' with error_detail — a failed run is always
// a visible record, never a silent green.
const SQL = `
CREATE TABLE IF NOT EXISTS gazette_sro_editions (
