import { NextResponse } from "next/server";
import { timingSafeEqual } from "node:crypto";
import {
  isProductionLikeRuntime,
  requireStrongSecret,
} from "@/lib/env/security";
import { runGazetteSroMonitorForAllTenants } from "@/modules/tax-rules/gazette-sro-monitor";

/**
 * Constant-time comparison — mirrors the pattern in payout-webhook/route.ts.
 * Length-check first to avoid the RangeError that timingSafeEqual throws on
 * unequal-length buffers; a length mismatch is itself a non-match.
 */
function secretsMatch(incoming: string, expected: string): boolean {
  const a = Buffer.from(incoming);
  const b = Buffer.from(expected);
  if (a.length !== b.length) return false;
  return timingSafeEqual(a, b);
}

/**
 * Fail-closed: if CRON_SECRET is not set the endpoint returns 401.
 * In local dev, set CRON_SECRET=any-value-at-least-32-chars in .env.local
 * and pass it as: Authorization: Bearer <secret>
 */
function authorizeCron(request: Request): boolean {
  const secret = isProductionLikeRuntime()
    ? requireStrongSecret("CRON_SECRET")
    : process.env.CRON_SECRET?.trim();
  if (!secret) return false;
  const auth = request.headers.get("authorization");
  const token = auth?.startsWith("Bearer ") ? auth.slice(7) : null;
  return token !== null && secretsMatch(token, secret);
}

/**
 * WC-209: real NBR SRO scrape path.
 *
 * Runs the gazette SRO monitor for every tenant: fetch the real NBR SRO
 * listing (nbr.gov.bd, SSRF-guarded), parse entries, and propose tax-rule
 * diffs for NEW editions through the existing gazette-monitor -> diff-agent
 * -> tax_rule_proposals flow (human approval still required downstream).
 *
 * FAIL-HONEST: any fetch/parse failure is persisted by the monitor as a
 * gazette_monitor_runs row with status='failed' (never a silent green), and
 * this route answers 500 when any tenant run failed so the cron invocation
 * itself is visibly red. 'partial' (proposal-level failures, e.g. LLM
 * unavailable) still answers 200 — those editions stay unmarked and retry
 * on the next run, and the partial run row records the detail.
 */
export async function GET(request: Request) {
  try {
    if (!authorizeCron(request)) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const ranAt = new Date().toISOString();
    const results = await runGazetteSroMonitorForAllTenants();
    const anyFailed = results.some((result) => result.status === "failed");

    console.info(
      JSON.stringify({
        route: "GET /api/cron/gazette-monitor",
        message: "gazette SRO monitor run complete",
        mode: "sro_monitor",
        tenants: results.length,
        failed: results.filter((result) => result.status === "failed").length,
        ts: ranAt,
      })
    );

    return NextResponse.json(
      { ok: !anyFailed, mode: "sro_monitor", results, ranAt },
      { status: anyFailed ? 500 : 200 }
    );
  } catch (err) {
    // TODO(logger): migrate to lib/logger
    console.error(
      JSON.stringify({
        route: "GET /api/cron/gazette-monitor",
        error: err instanceof Error ? err.message : String(err),
        ts: new Date().toISOString(),
      })
    );
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function POST(request: Request) {
  return GET(request);
}

