// not pass this gate forever after the deployment moves on (AR P2 #2).
const PROOF_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000;
const provedSources = (adapterStatus?.sources || []).filter(
  (source) => source.livePullMode === "live-pull" && source.livePullSourceSha
);
if (provedSources.length > 0) {
  const freshSources = provedSources.filter((source) => {
    const pulledAt = Date.parse(source.livePullAt || "");
    return Number.isFinite(pulledAt) && Date.now() - pulledAt <= PROOF_MAX_AGE_MS;
  });
  if (freshSources.length > 0) {
