import { sourceRegistry } from "../registry.js";
import { collectGaps } from "./evidence.js";

export function buildReleaseGates({ snapshots, scorecards, adapterStatus, alertGateway, storage, noWriteFindings = [], ciProvenance }) {
  const latestBySource = latestSnapshotMap(snapshots);
  const gaps = collectGaps(snapshots);
  const adapterBySource = new Map((adapterStatus?.sources || []).map((source) => [source.sourceSystem, source]));
  // WC-211 ci_provenance evidence: the honest anchor is a committed live-health
  // pull proof (real source sha). When present the gate PASSES; when absent it
  // SKIPs with a reason — never an unconditional warn.
  const ciProvenanceEvidence = resolveCiProvenanceEvidence(adapterStatus, ciProvenance);

  const products = sourceRegistry.map((source) => {
    const snapshot = latestBySource.get(source.id);
    const adapter = adapterBySource.get(source.id);
    const sourceGaps = gaps.filter((gap) => gap.sourceSystem === source.id);
    const sourceScorecards = scorecards.filter((card) => card.sourceSystems.includes(source.id));
    const freshness = sourceScorecards.flatMap((card) => card.freshness || []).find((item) => item.sourceSystem === source.id);
    const adapterReady = Boolean(adapter?.lastPullOk === true || adapter?.deploymentState === "os_side_health_importer");

    const gates = [
      gate("source_registered", "Source registry", "pass", `${source.productName} is registered as a BishomIQOS vertical.`),
      gate("snapshot_contract", "Snapshot contract", snapshot && snapshot.connectorMode === "read_only" ? "pass" : "block", snapshot ? "Latest snapshot is read-only." : "No latest snapshot exists."),
      gate(
        "adapter_surface",
        "Adapter surface",
        adapterReady ? "pass" : "warn",
        adapterReady
          ? "Adapter has a successful pull proof or is OS-side imported."
          : adapter?.canPullNow
            ? "Adapter token is configured, but no successful pull proof is recorded yet."
            : "Adapter cannot be pulled from this OS runtime yet."
      ),
      gate("freshness", "Freshness", freshness?.status === "fresh" ? "pass" : "warn", freshness?.message || "Freshness is unknown."),
      gate("client_claims", "Client-safe claims", sourceGaps.some((item) => item.blocksReport || item.severity === "p0") ? "block" : sourceGaps.length ? "warn" : "pass", summarizeGaps(sourceGaps))
    ];

    return {
      sourceSystem: source.id,
      productName: source.productName,
      status: worstStatus(gates.map((item) => item.status)),
      gates
    };
  });

  const portfolioGates = [
    gate("read_only_boundary", "Read-only boundary", noWriteFindings.length ? "block" : "pass", noWriteFindings.length ? `${noWriteFindings.length} forbidden write pattern(s) found.` : "No forbidden source-write pattern found in OS repo."),
    gate(
      "durable_os_storage",
      "Durable OS storage",
      storage?.durable ? "pass" : "block",
      storage?.durable
        ? `OS-owned snapshots and action events use ${storage.mode}.`
        : storage?.reason || "Durable OS-owned storage is not configured."
    ),
    gate("alert_gateway", "Alert gateway", alertGateway?.ready === true ? "pass" : "warn", alertGateway?.ready === true ? alertGateway.boundary : "Gateway must be proved through the protected probe before this gate passes."),
    // WC-211 WINNABLE GATE: ci_provenance is no longer an unconditional warn.
    // PASS when provenance evidence is present (a committed live-health pull
    // proof carrying a real source sha). SKIP-with-reason when absent — honest
    // non-readiness, not a fabricated or permanent warn. Never warn blindly.
    gate(
      "ci_provenance",
      "CI provenance",
      ciProvenanceEvidence.present ? "pass" : "skip",
      ciProvenanceEvidence.summary
    ),
    gate("snapshot_coverage", "Snapshot coverage", distinctSourceCount(snapshots) >= sourceRegistry.length ? "pass" : "block", `${distinctSourceCount(snapshots)}/${sourceRegistry.length} registered source systems have snapshots loaded.`),
    gate("client_report_pack", "Client report pack", products.some((product) => product.status === "block") ? "block" : products.some((product) => product.status === "warn") ? "warn" : "pass", "Client report status follows product gate outcomes.")
  ];

  return {
    generatedAt: new Date().toISOString(),
    overallStatus: worstStatus([...portfolioGates, ...products.flatMap((product) => product.gates)].map((item) => item.status)),
    portfolioGates,
    products
  };
}

function gate(id, title, status, summary) {
  return { id, title, status, summary };
}

/**
 * WC-211 ci_provenance evidence resolver.
 *
 * Honest provenance anchor: a committed live-health pull proof (real source
 * sha). The gate is winnable — PASS when evidence exists, SKIP-with-reason
 * when it does not. We never fabricate a warn.
 *
 * Evidence sources, in priority order:
 *   1. Explicit `ciProvenance` override (tests / future CI wiring).
 *   2. adapterStatus.sources[].livePullSourceSha — set by buildSourceAdapterStatus
 *      when a committed live-health pull proof exists for a source.
 *
 * @returns {{ present: boolean, summary: string }}
 */
function resolveCiProvenanceEvidence(adapterStatus, ciProvenance) {
  if (ciProvenance && typeof ciProvenance === "object") {
    if (ciProvenance.present === true) {
      return {
        present: true,
        summary: ciProvenance.summary || "CI provenance evidence is present."
      };
    }
    if (ciProvenance.present === false) {
      return {
        present: false,
        summary: ciProvenance.summary || "CI provenance evidence is absent; gate skipped until evidence is recorded."
      };
    }
  }

  const provedSources = (adapterStatus?.sources || []).filter(
    (source) => source.livePullMode === "live-pull" && source.livePullSourceSha
  );
  if (provedSources.length > 0) {
    const list = provedSources
      .map((source) => `${source.sourceSystem}@${String(source.livePullSourceSha).slice(0, 10)}`)
      .join(", ");
    return {
      present: true,
      summary: `Provenance anchored by committed live-health pull proof: ${list}.`
    };
  }

  return {
    present: false,
    summary: "No CI provenance evidence recorded yet (no committed live-health pull proof and no GitLab pipeline link). Gate skipped — not warned — until evidence is present."
  };
}

function summarizeGaps(gaps) {
  if (!gaps.length) return "No source gaps are open.";
  const blocker = gaps.find((gapItem) => gapItem.blocksReport || gapItem.severity === "p0");
  if (blocker) return blocker.summary;
  return `${gaps.length} non-blocking gap(s) require owner review.`;
}

function worstStatus(statuses) {
  // Precedence: block > warn > skip > pass.
  // "skip" is an honest non-readiness state (WC-211) — it does NOT escalate to
  // warn, but a real warn/block elsewhere still wins.
  if (statuses.includes("block")) return "block";
  if (statuses.includes("warn")) return "warn";
  if (statuses.includes("skip")) return "skip";
  return "pass";
}

function distinctSourceCount(snapshots) {
  return new Set(snapshots.map((snapshot) => snapshot.sourceSystem)).size;
}

function latestSnapshotMap(snapshots) {
  const bySource = new Map();
  for (const snapshot of snapshots) {
    const current = bySource.get(snapshot.sourceSystem);
    if (!current || snapshotTime(snapshot) > snapshotTime(current)) {
      bySource.set(snapshot.sourceSystem, snapshot);
    }
  }
  return bySource;
}

function snapshotTime(snapshot) {
  const collectedAt = Date.parse(snapshot.collectedAt || "");
  if (Number.isFinite(collectedAt)) return collectedAt;
  const sealedAt = Date.parse(snapshot.sealedAt || "");
  return Number.isFinite(sealedAt) ? sealedAt : 0;
}

