export interface WebHealthReport {
  readonly ok: boolean;
  readonly service: "aurasphere-web";
  readonly deployed_sha: string;
  readonly deployed_sha_source: string;
  readonly dependencies: {
    readonly gateway_origin: {
      readonly ok: boolean;
      readonly source: "env" | "missing" | "invalid";
      /** Normalized origin (trailing slashes stripped); null when unset/invalid. */
      readonly value: string | null;
      readonly note?: string;
