    if (value) return { value, source: key };
  }
  return { value: "unknown", source: "missing" };
}

function resolveGatewayOrigin(env: Env): WebHealthReport["dependencies"]["gateway_origin"] {
  const raw = env.NEXT_PUBLIC_GATEWAY_URL?.trim();
  if (!raw) {
    return {
      ok: false,
      source: "missing",
      value: null,
      // Honest about the client dev-fallback (lib/api.ts): unset means the shell
      // would call http://localhost:8080 — fine locally, wrong in production.
      note: "NEXT_PUBLIC_GATEWAY_URL unset; client falls back to http://localhost:8080",
    };
  }
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return { ok: false, source: "invalid", value: null, note: "not a valid absolute URL" };
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    return { ok: false, source: "invalid", value: null, note: "scheme must be http(s)" };
  }
  return { ok: true, source: "env", value: raw.replace(/\/+$/, "") };
}

