  const deployed = resolveDeployedSha(env);
  const gatewayOrigin = resolveGatewayOrigin(env);
  return {
    ok: deployed.value !== "unknown" && gatewayOrigin.ok,
    service: "aurasphere-web",
    deployed_sha: deployed.value,
    deployed_sha_source: deployed.source,
    dependencies: { gateway_origin: gatewayOrigin },
  };
}
