/**
 * Khep task-desk INPUT wiring (WC-003).
 *
 * The task-desk page feeds a real 1049-line current-truth engine
 * (buildKhepTaskLedger) from a hardcoded SEED task whose `persistentRules` were
 * also hardcoded. The real persistent-context store
 * (readPersistentContextRules / persistent-context-rules.json) is the live input
 * path the desk was built to read from — the same path POST /api/khep/tasks
 * already uses. This module wires the desk to that real store.
 *
 * Honesty contract: the seed rule below is an EXAMPLE only. It is NEVER injected
 * into the live store. It feeds the current-truth engine solely as a clearly
 * labeled fallback when the live store is empty, so a fresh install never renders
 * an empty Persistent-context panel as if no rules existed. The moment an
 * operator stores a real rule (POST /api/khep/context/rules), the live store
 * rules replace this seed entirely and `source` flips to "persistent-context-store".
 */
import type { PersistentContextRule } from "./current-truth-engine";
import { peekPersistentContextRules, type StoredPersistentContextRule } from "./persistent-context-store";

/**
 * The honest EXAMPLE rule the task-desk falls back to when the live
 * persistent-context store is empty. Labeled seed, not live data.
 */
export const OPERATORBENCH_SEED_FALLBACK_RULE: PersistentContextRule = {
  id: "operatorbench-supervised-trial-blocker",
  scope: "operatorbench-client-trial",
  instruction:
    "Keep supervised client trial status blocked until Gmail and Drive tokens plus OAuth scope evidence are provided by the operator.",
  triggers: ["gmail", "drive", "client trial", "supervised"],
};

export type TaskDeskRuleSource = "persistent-context-store" | "seed-fallback";

export interface ResolvedTaskDeskRules {
  rules: PersistentContextRule[];
  /** Where the rules came from — surfaced in the desk UI so the seed fallback is
   * always visible and never mistaken for live stored rules. */
  source: TaskDeskRuleSource;
  /** True iff the live store was empty and the labeled seed was used instead. */
  usedSeedFallback: boolean;
}

/**
 * Maps a stored rule down to the engine's PersistentContextRule contract so the
 * desk never feeds store-internal bookkeeping fields (fingerprint,
 * occurrenceCount, evidenceExamples, createdAt, updatedAt) into the engine.
 */
function toEngineRule(stored: StoredPersistentContextRule): PersistentContextRule {
  return {
    id: stored.id,
    scope: stored.scope,
    instruction: stored.instruction,
    triggers: stored.triggers,
    pitfallTemplate: stored.pitfallTemplate,
    priority: stored.priority,
    version: stored.version,
    expiresAt: stored.expiresAt,
  };
}

/**
 * Resolves the task-desk's persistent rules from the REAL persistent-context
 * store (the live input path), falling back to the labeled seed rule ONLY when
 * the store is empty. Pure read — never writes or creates the store directory.
 */
export function resolveTaskDeskPersistentRules(): ResolvedTaskDeskRules {
  const stored = peekPersistentContextRules();
  if (stored.length > 0) {
    return {
      rules: stored.map(toEngineRule),
      source: "persistent-context-store",
      usedSeedFallback: false,
    };
  }
  return {
    rules: [OPERATORBENCH_SEED_FALLBACK_RULE],
    source: "seed-fallback",
    usedSeedFallback: true,
  };
}

