export function blockIfNotCurrent(snapshot: ContextSnapshot, productKey: string, action: string): ClaimPreflightResult {
  const record = snapshot.products[productKey];
  if (!record) {
    return {
      verdict: 'BLOCK',
      claim: action,
      blockers: [
        {
          id: `unknown-product-${productKey}`,
          severity: 'P0',
          proof_family: 'currentness',
          summary: `Unknown product "${productKey}".`,
          required_action: 'Use a canonical product key from the manifest.',
        },
      ],
      required_proof: ['currentness'],
    };
  }

  const blockers = [...authorityClaimBlockers(productKey, action, record.product.authority_matrix), ...record.currentness.blockers];

  return {
    verdict: record.currentness.verdict === 'PASS' && blockers.length === 0 ? 'PASS' : 'BLOCK',
    claim: action,
    blockers,
    required_proof: ['authority_matrix', 'source_currentness', 'ci_or_ship_authority', 'runtime_health'],
  };
}

