/**
 * Unmissable freshness envelope for a product's live probe. Surfaced at the TOP
 * of get_current_truth / block_if_not_current so a stale probe can never be read
 * as current state. `is_stale` means the probe is older than the product's
 * freshness SLA (or absent): the deploy_sha/health below it are UNVERIFIED and
 * must not be cited — re-anchor first (`anchor-probe <key> --apply`).
 *
 * This is the mechanical backstop for the recurring failure of citing a stale
 * state-card's deploy_sha as the live one (state-cards != live deploys).
 */
export interface FreshnessSummary {
  is_stale: boolean;
  probe_generated_at: string | null;
  probe_age_minutes: number | null;
  sla_minutes: number;
  deploy_sha: string | null;
  origin_main_sha: string | null;
  sha_drift: boolean;
  health: string | null;
  /** When stale/absent, the served deploy_sha/health are unverified. */
  deploy_state_unverified: boolean;
  required_action: string | null;
}

export function summarizeProbeFreshness(record: ContextProductRecord, nowIso = new Date().toISOString()): FreshnessSummary {
  const slaMinutes = QUALITY_BAR_PROFILES[record.standard.qualityBarProfile].freshness_sla_minutes;
  const probe = record.product.live_probe;
  const generatedAt = probe?.generated_at ?? null;
  const fresh = isFresh(generatedAt, slaMinutes, nowIso);
  let ageMinutes: number | null = null;
  if (generatedAt) {
    const ageMs = Date.parse(nowIso) - new Date(generatedAt).getTime();
    ageMinutes = Number.isNaN(ageMs) ? null : Math.round(ageMs / 60_000);
  }
  const deploySha = probe?.deploy_sha ?? null;
  const originMainSha = probe?.origin_main_sha ?? null;
  return {
    is_stale: !fresh,
    probe_generated_at: generatedAt,
    probe_age_minutes: ageMinutes,
    sla_minutes: slaMinutes,
    deploy_sha: deploySha,
    origin_main_sha: originMainSha,
    sha_drift: Boolean(deploySha && originMainSha && deploySha !== originMainSha),
    health: probe?.health ?? null,
    deploy_state_unverified: !fresh,
    required_action: fresh
      ? null
      : `STALE probe (${ageMinutes ?? 'unknown'}m old, SLA ${slaMinutes}m): deploy_sha/health below are UNVERIFIED. Re-anchor before citing live state — run: npx tsx scripts/anchor-probe.ts ${record.product.key} --apply`,
  };
}

