input.new_string:
server.registerTool(
  'get_current_truth',
  {
    description:
      'Return current truth for one product. The result LEADS with a `freshness` gate: when `is_stale`, the deploy_sha/health are UNVERIFIED — do not cite them as live state. Pass refresh:true to best-effort re-anchor (runs anchor-probe) a stale product before answering.',
    inputSchema: { product: z.string(), refresh: z.boolean().optional() },
  },
  async ({ product, refresh }) => {
    let snapshot = buildContextSnapshot();
    let record = snapshot.products[product];
    if (!record) {
      return toolResult({ verdict: 'BLOCK', reason: `Unknown product "${product}"` });
    }
    // Opt-in, best-effort auto-refresh: if the caller asked and the probe is
    // stale, re-anchor (bounded, non-fatal) and rebuild from fresh state.
    if (refresh && summarizeProbeFreshness(record).is_stale) {
      const refreshOutcome = tryReanchorProduct(product);
      if (refreshOutcome.ok) {
        snapshot = buildContextSnapshot();
        record = snapshot.products[product] ?? record;
      }
      return toolResult({ refresh_attempted: refreshOutcome, ...renderCurrentTruth(record) });
    }
    return toolResult(renderCurrentTruth(record));
  },
);

