import { execFileSync } from 'node:child_process';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';
import { buildContextSnapshot, findBestReference, findCodeSnippets, renderCurrentTruth, searchWiki, summarizeProbeFreshness } from './engine.js';
import { REPO_ROOT } from '../../scripts/state-lib.js';

/**
 * Best-effort, bounded, NON-FATAL re-anchor of one product (runs
 * `anchor-probe <key> --apply`). Never throws and never hangs the tool: any
 * failure (network, token, timeout) returns { ok:false } so get_current_truth
 * still answers, now with an honest stale `freshness` envelope. Opt-in only
 * (refresh:true) so the default read path stays pure and side-effect-free.
 */
function tryReanchorProduct(product: string): { ok: boolean; reason?: string } {
  try {
    execFileSync('npx', ['tsx', 'scripts/anchor-probe.ts', product, '--apply'], {
      cwd: REPO_ROOT,
      timeout: 90_000,
      stdio: 'pipe',
      shell: true,
    });
    return { ok: true };
  } catch (error) {
    const reason = error instanceof Error ? error.message.split('\n')[0] : String(error);
    return { ok: false, reason: `re-anchor failed (non-fatal): ${reason}` };
  }
}

