        ? { generated_at: generatedAt, deploy_sha: deploySha, origin_main_sha: deploySha, runtime_sha: deploySha, health: '200', working_probe: true, drift_warnings: [] }
        : undefined,
    },
    standard: { qualityBarProfile: 'customer_app' },
    manifest: {},
    currentness: { verdict: 'PASS', blockers: [] },
    bar_status: { at_bar: true, claim_blocked: false, blockers: [], evidence_refs: [] },
    card_verdict: 'OK',
    card_contradictions: [],
    claim_verdicts: [],
  } as unknown as ContextProductRecord;
}

test('freshness gate: a stale probe is flagged is_stale with an unmissable required_action', () => {
  const stale = summarizeProbeFreshness(recordWithProbe('2026-07-01T00:00:00.000Z'), '2026-07-25T00:00:00.000Z');
  assert.equal(stale.is_stale, true);
  assert.equal(stale.deploy_state_unverified, true);
  assert.match(stale.required_action ?? '', /STALE probe/);
  assert.match(stale.required_action ?? '', /anchor-probe/);
  assert.ok((stale.probe_age_minutes ?? 0) > 120);
});

test('freshness gate: a fresh probe passes clean (no required_action)', () => {
  const now = new Date().toISOString();
  const fresh = summarizeProbeFreshness(recordWithProbe(now), now);
  assert.equal(fresh.is_stale, false);
  assert.equal(fresh.deploy_state_unverified, false);
  assert.equal(fresh.required_action, null);
});

test('freshness gate: a missing probe is treated as stale, never throws', () => {
  const none = summarizeProbeFreshness(recordWithProbe(null));
  assert.equal(none.is_stale, true);
  assert.equal(none.deploy_sha, null);
  assert.match(none.required_action ?? '', /anchor-probe/);
});

