  const rendered = renderCurrentTruth(recordWithProbe('2026-07-01T00:00:00.000Z', 'deadbeefdeadbeefdeadbeefdeadbeefdeadbeef'));
  assert.ok(rendered.freshness, 'freshness must be present on get_current_truth output');
  assert.equal(rendered.freshness.is_stale, true);
});
