if (route.handlerStub === "payments.intent") {
  if (!ctx?.paymentIntent) {
    return mapErrorToResponse(appError("validation", "payment intent body required"));
  }
  const idor = await assertOwnBooking(deps.booking.bookingRepo, ctx.paymentIntent.booking_id, principalId);
  if (!idor.ok) return mapErrorToResponse(idor.error);
  // AMOUNT AUTHORITY: the intent amount is the booking's server-set fee_paisa,
  // NEVER the client-supplied value. A mismatching client amount is rejected
  // loudly (tampering/bug signal); the authoritative fee is what gets persisted
  // and (once rails are live) captured — so a patient can never mint an intent
  // for their own booking at an arbitrary amount.
  const authoritativeAmount = idor.value.fee_paisa;
  if (Number(ctx.paymentIntent.amount_paisa) !== Number(authoritativeAmount)) {
    return mapErrorToResponse(
      appError("validation", "amount_paisa must equal the booking fee", {
        booking_id: ctx.paymentIntent.booking_id,
      }),
    );
  }
  const r = await deps.payments.createIntent({ ...ctx.paymentIntent, amount_paisa: authoritativeAmount });
  if (!r.ok) return mapErrorToResponse(r.error);
  return { status: 200, body: r.value };
}

