216	        $expired += [string]$entry.effect_key
217	      }
218	    }
219	    [ordered]@{
220	      code = 'WOC-D000'
221	      kind = 'wire-or-cut-tick'
222	      expired_effect_keys = @($expired)
223	      expired_lease_count = @($expired).Count
224	      required_action = 'ObserveRetry'
225	    } | ConvertTo-Json -Compress | Write-Output
226	    exit 0
227	  }
228	
229	  if ($Mode -eq 'RebuildSnapshot') {
230	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
231	    if (-not (Test-Path -LiteralPath $eventsPath -PathType Leaf)) {
232	      Stop-WireCutDispatch 'WOC-D009' 'Event ledger file is missing.'
233	    }
234	    $events = Read-WireCutDispatchEvents -EventsPath $eventsPath
235	    if ($null -eq $events) { Stop-WireCutDispatch 'WOC-D009' 'Event ledger is corrupt.' }
236	    if (@($events).Count -lt 1) {
237	      $raw = [IO.File]::ReadAllText($eventsPath)
238	      Stop-WireCutDispatch 'WOC-D009' "Event ledger is empty (bytes=$($raw.Length))."
239	    }
240	    $init = $events | Where-Object { [string]$_.type -eq 'sequence_init' } | Select-Object -First 1
241	    if ($null -eq $init) { Stop-WireCutDispatch 'WOC-D009' 'Initialization event is missing.' }
242	    $planCommit = [string]$init.plan_commit
243	    $registry = Read-WireCutDispatchRegistryAtCommit -GitCommand $GitCommand -Workspace $resolvedWorkspace -Commit $planCommit
244	    if ($null -eq $registry) { Stop-WireCutDispatch 'WOC-D004' 'Bound plan registry cannot be read for rebuild.' }
245	    $binding = [ordered]@{
246	      plan_commit = $planCommit
247	      registry_sha256 = [string]$init.registry_sha256
248	    }
249	    $rebuilt = Invoke-WireCutReplayEvents -Registry $registry -PlanBinding $binding -Events $events
250	    if ($null -eq $rebuilt) { Stop-WireCutDispatch 'WOC-D009' 'Replay rebuild failed.' }
251	    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
252	    Write-WireCutCanonicalJson -Path $snapshotPath -Object $rebuilt
253	    Emit-WireCutDispatchSuccess 'rebuild snapshot from events complete'
254	  }
255	
256	  if ($Mode -eq 'ReplayVerify') {
257	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
258	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
259	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
260	    $events = Read-WireCutDispatchEvents -EventsPath $eventsPath
261	    $rebuilt = Invoke-WireCutReplayEvents -Registry $tickCheck.registry -PlanBinding $tickCheck.snapshot.plan_binding -Events $events
262	    if ($null -eq $rebuilt) { Stop-WireCutDispatch 'WOC-D009' 'Replay rebuild failed.' }
263	    $left = Get-WireCutCanonicalJsonSha256 -Object (Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot)
264	    $right = Get-WireCutCanonicalJsonSha256 -Object $rebuilt
265	    if ($left -ne $right) { Stop-WireCutDispatch 'WOC-D009' 'Replay digest does not match snapshot.' }
266	    Emit-WireCutDispatchSuccess 'replay verify passed'
267	  }
268	
269	  if ($Mode -eq 'RegisterSynthetic') {
270	    if (-not $TestMode) { Stop-WireCutDispatch 'WOC-D099' 'RegisterSynthetic is test-only.' }
271	    if ($SyntheticLeaves.Count -lt 1) { Stop-WireCutDispatch 'WOC-D011' 'SyntheticLeaves is required.' }
272	    Assert-WireCutExpectedAbsentCas
273	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
274	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
275	    $snapshot = Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot
276	    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
277	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
278	    $events = @()
279	    foreach ($leaf in @($SyntheticLeaves)) {
280	      if (Test-WireCutWorkPackageExists -WorkPackages $snapshot.work_packages -EffectKey $leaf) { continue }
281	      Set-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $leaf -Entry (New-WireCutPackageRuntimeEntry -EffectKey $leaf -SeedStatus 'pending')
282	      $entry = Get-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $leaf
283	      $entry | Add-Member -NotePropertyName 'class' -NotePropertyValue $PackageClass -Force
284	      $events += [ordered]@{
285	        type = 'synthetic_register'
286	        effect_key = $leaf
287	        class = $PackageClass
288	      }
289	    }
290	    if ($events.Count -lt 1) { Stop-WireCutDispatch 'WOC-D011' 'Synthetic leaf already exists.' }
291	    $write = Invoke-WireCutDispatchStateWrite -GitCommand $GitCommand -Workspace $resolvedWorkspace `
292	      -SnapshotPath $snapshotPath -EventsPath $eventsPath -SnapshotObject $snapshot -EventObjects $events `
293	      -CommitMessage 'wire-or-cut: register synthetic leaves'
294	    if (-not $write.ok) {
295	      if ($write.reason -eq 'push_rejected_non_ff') { Stop-WireCutDispatch 'WOC-D007' 'Synthetic register push rejected (non-fast-forward).' }
296	      Stop-WireCutDispatch 'WOC-D006' "Synthetic register failed: $($write.reason)"
297	    }
298	    Emit-WireCutDispatchSuccess ("synthetic leaves registered: " + ($SyntheticLeaves -join ','))
299	  }
300	
301	  if ($Mode -eq 'Transition') {
302	    if ([string]::IsNullOrWhiteSpace($EffectKey) -or [string]::IsNullOrWhiteSpace($ToStatus)) {
303	      Stop-WireCutDispatch 'WOC-D011' 'Transition requires EffectKey and ToStatus.'
304	    }
305	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
306	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
307	    $snapshot = Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot
308	    if (-not (Test-WireCutWorkPackageExists -WorkPackages $snapshot.work_packages -EffectKey $EffectKey)) {
309	      Stop-WireCutDispatch 'WOC-D011' "Unknown effect_key $EffectKey."
310	    }
311	    $entry = Get-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $EffectKey
312	    Assert-WireCutExpectedCas -Entry $entry
313	    if ($null -ne $entry.lease -and (Test-WireCutLeaseLive -Lease $entry.lease) -and $ToStatus -eq 'leased') {
314	      Stop-WireCutDispatch 'WOC-D012' 'Live unexpired lease blocks redispatch.'
315	    }
316	    # Registry waivers[] are an operator governance mechanism; this dispatcher
317	    # has no waiver mutation verb, so it never manufactures a waived status.
318	    $valid = @('pending', 'leased', 'dispatched', 'reviewing', 'blocked', 'done')
319	    if ($valid -notcontains $ToStatus) { Stop-WireCutDispatch 'WOC-D011' "Invalid target status $ToStatus." }
320	    $fromStatus = [string]$entry.status
321	    $allowed = @{
322	      pending = @('leased')
323	      leased = @('dispatched')
324	      dispatched = @('reviewing')
325	      reviewing = @('done', 'blocked')
326	    }
327	    if (-not $allowed.ContainsKey($fromStatus) -or $allowed[$fromStatus] -notcontains $ToStatus) {
328	      Stop-WireCutDispatch 'WOC-D011' "Transition $fromStatus -> $ToStatus is not allowed."
329	    }
330	    $event = [ordered]@{
331	      type = 'status_transition'
332	      effect_key = $EffectKey
333	      from_status = $fromStatus
334	      to_status = $ToStatus
335	      attempt_id = [int]$entry.attempt_id
336	    }
337	    $entry.status = $ToStatus
338	    if ($ToStatus -eq 'leased') {
339	      if ([string]::IsNullOrWhiteSpace($OwnerSession)) {
340	        Stop-WireCutDispatch 'WOC-D011' 'Lease transition requires OwnerSession.'
341	      }
342	      $expires = [DateTime]::UtcNow.AddMinutes($LeaseMinutes).ToString('o')
343	      if ($TestMode -and $LeaseMinutes -lt 0) {
344	        $expires = [DateTime]::UtcNow.AddMinutes($LeaseMinutes).ToString('o')
345	      }
346	      $lease = [ordered]@{
347	        owner_session = $OwnerSession
348	        attempt_id = [int]$entry.attempt_id
349	        expires_at = $expires
350	        effect_key = $EffectKey
351	      }
352	      $entry.lease = $lease
353	      $event.lease = $lease
354	    } elseif ($ToStatus -in @('dispatched', 'reviewing', 'done', 'blocked')) {
355	      if ($null -ne $entry.lease) { $event.clear_lease = $true }
356	      $entry.lease = $null
357	    }
358	    if ($ToStatus -eq 'done') {
359	      $class = $PackageClass
360	      if ($entry.PSObject.Properties['class']) { $class = [string]$entry.class }
361	      if ([string]::IsNullOrWhiteSpace($CompletionEvidencePath) -or -not (Test-Path -LiteralPath $CompletionEvidencePath -PathType Leaf)) {
362	        Stop-WireCutDispatch 'WOC-D011' 'Done transition requires CompletionEvidencePath.'
363	      }
364	      $evidence = Get-Content -Raw -LiteralPath $CompletionEvidencePath -Encoding utf8 | ConvertFrom-Json
365	      if (-not (Test-WireCutCompletionEvidence -Registry $tickCheck.registry -Class $class -Evidence $evidence -PackageId $EffectKey)) {
366	        Stop-WireCutDispatch 'WOC-D011' 'Completion evidence does not satisfy the class-typed contract.'
367	      }
368	      $entry.completion_evidence_refs = $evidence
369	      $event.completion_evidence_refs = $evidence
370	    }
371	    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
372	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
373	    if ($NoPush) {
374	      $mutation = Write-WireCutDispatchStateMutation -SnapshotPath $snapshotPath -EventsPath $eventsPath `
375	        -SnapshotObject $snapshot -EventObjects @($event)
376	      Emit-WireCutDispatchSuccess "transition staged locally $fromStatus->$ToStatus effect_key=$EffectKey sequence=$($mutation.sequence)"
377	    } else {
378	      $write = Invoke-WireCutDispatchStateWrite -GitCommand $GitCommand -Workspace $resolvedWorkspace `
379	        -SnapshotPath $snapshotPath -EventsPath $eventsPath -SnapshotObject $snapshot -EventObjects @($event) `
380	        -CommitMessage "wire-or-cut: $EffectKey $fromStatus->$ToStatus"
381	      if (-not $write.ok) {
382	        if ($write.reason -eq 'push_rejected_non_ff') { Stop-WireCutDispatch 'WOC-D007' 'Transition push rejected (non-fast-forward); re-read required.' }
383	        Stop-WireCutDispatch 'WOC-D006' "Transition write failed: $($write.reason)"
384	      }
385	      Emit-WireCutDispatchSuccess "transition $fromStatus->$ToStatus effect_key=$EffectKey sequence=$($write.sequence)"
386	    }
387	  }
388	
389	  if ($Mode -eq 'ObserveRetry') {
390	    if ([string]::IsNullOrWhiteSpace($EffectKey)) { Stop-WireCutDispatch 'WOC-D011' 'ObserveRetry requires EffectKey.' }
391	    if ([string]::IsNullOrWhiteSpace($ObserveResultPath) -or -not (Test-Path -LiteralPath $ObserveResultPath -PathType Leaf)) {
392	      Stop-WireCutDispatch 'WOC-D013' 'ObserveRetry requires ObserveResultPath.'
393	    }
394	    $tickCheck = Invoke-WireCutDispatchTickPreflight -GitCommand $GitCommand -NodeCommand $NodeCommand -Workspace $resolvedWorkspace -Mode 'Tick'
395	    if (-not $tickCheck.ok) { Stop-WireCutDispatch $tickCheck.code $tickCheck.message }
396	    $snapshot = Copy-WireCutDispatchSnapshotObject -Snapshot $tickCheck.snapshot
397	    if (-not (Test-WireCutWorkPackageExists -WorkPackages $snapshot.work_packages -EffectKey $EffectKey)) {
398	      Stop-WireCutDispatch 'WOC-D011' "Unknown effect_key $EffectKey."
399	    }
400	    $entry = Get-WireCutWorkPackageEntry -WorkPackages $snapshot.work_packages -EffectKey $EffectKey
401	    Assert-WireCutExpectedCas -Entry $entry
402	    $liveLease = $null -ne $entry.lease -and (Test-WireCutLeaseLive -Lease $entry.lease)
403	    if ($liveLease) {
404	      Stop-WireCutDispatch 'WOC-D012' 'Live unexpired lease blocks observe-before-retry.'
405	    }
406	    $expiredLease = $null -ne $entry.lease
407	    if ([string]$entry.status -ne 'blocked' -and -not $expiredLease) {
408	      Stop-WireCutDispatch 'WOC-D013' 'ObserveRetry requires a blocked package or an expired lease.'
409	    }
410	    $observe = Get-Content -Raw -LiteralPath $ObserveResultPath -Encoding utf8 | ConvertFrom-Json
411	    $snapshotPath = Join-Path $resolvedWorkspace $script:WireCutDispatchStateRelative
412	    $eventsPath = Join-Path $resolvedWorkspace $script:WireCutDispatchEventsRelative
413	    $oldAttempt = [int]$entry.attempt_id
414	    $newAttempt = $oldAttempt + 1
415	    $entry.status = 'blocked'
416	    $entry.lease = $null
417	    $tombstone = [ordered]@{
418	      type = 'attempt_tombstone'
419	      effect_key = $EffectKey
420	      attempt_id = $oldAttempt
421	      reason = if ($expiredLease) { 'lease_expired' } else { 'blocked_observe_retry' }
422	    }
423	    $reconciledStatus = 'pending'
424	    if ($observe.PSObject.Properties['external_done'] -and [bool]$observe.external_done) {
425	      $reconciledStatus = 'reviewing'
426	    }
427	    $reconcile = [ordered]@{
428	      type = 'observe_reconcile'
429	      effect_key = $EffectKey
430	      to_status = $reconciledStatus
431	      new_attempt_id = $newAttempt
432	      observed = $observe
433	    }
434	    $entry.status = $reconciledStatus
435	    $entry.attempt_id = $newAttempt
436	    $entry.lease = $null
437	    $write = Invoke-WireCutDispatchStateWrite -GitCommand $GitCommand -Workspace $resolvedWorkspace `
438	      -SnapshotPath $snapshotPath -EventsPath $eventsPath -SnapshotObject $snapshot -EventObjects @($tombstone, $reconcile) `
439	      -CommitMessage "wire-or-cut: observe-reconcile $EffectKey -> $reconciledStatus fence=$newAttempt"
440	    if (-not $write.ok) {
441	      if ($write.reason -eq 'push_rejected_non_ff') { Stop-WireCutDispatch 'WOC-D007' 'Observe reconcile push rejected (non-fast-forward).' }
442	      Stop-WireCutDispatch 'WOC-D006' "Observe reconcile write failed: $($write.reason)"
443	    }
444	    Emit-WireCutDispatchSuccess "observe-retry complete effect_key=$EffectKey new_attempt_id=$newAttempt status=$reconciledStatus"
445	  }
446	
447	  Stop-WireCutDispatch 'WOC-D099' "Unsupported mode $Mode."
448	} finally {
449	  if ($mutexHeld) { $mutex.ReleaseMutex() | Out-Null }
450	  if ($null -ne $mutex) { $mutex.Dispose() }
451	}
