13	function Get-WireCutCanonicalTextSha256 {
14	  param([Parameter(Mandatory)][string]$Path)
15	  $text = [IO.File]::ReadAllText($Path)
16	  if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
17	  $text = $text.Replace("`r`n", "`n").Replace("`r", "`n")
18	  $bytes = [Text.UTF8Encoding]::new($false).GetBytes($text)
19	  $algorithm = [Security.Cryptography.SHA256]::Create()
20	  try { return ([BitConverter]::ToString($algorithm.ComputeHash($bytes))).Replace('-', '').ToLowerInvariant() }
21	  finally { $algorithm.Dispose() }
22	}
