35	function Write-WireCutCanonicalJson {
36	  param(
37	    [Parameter(Mandatory)][string]$Path,
38	    [Parameter(Mandatory)]$Object,
39	    [int]$Depth = 30,
40	    [switch]$FailBeforePublish
41	  )
42	  $dir = Split-Path -Parent $Path
43	  if ($dir -and -not (Test-Path -LiteralPath $dir -PathType Container)) {
44	    New-Item -ItemType Directory -Path $dir -Force | Out-Null
45	  }
46	  $json = ($Object | ConvertTo-Json -Depth $Depth) + "`n"
47	  $json = $json.Replace("`r`n", "`n").Replace("`r", "`n")
48	  $bytes = [Text.UTF8Encoding]::new($false).GetBytes($json)
49	  $tmp = Join-Path $dir ('.' + [IO.Path]::GetFileName($Path) + '.' + $PID + '.' + [guid]::NewGuid().ToString('N') + '.tmp')
50	  $backup = $tmp + '.bak'
51	  try {
52	    $stream = [IO.File]::Open($tmp, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
53	    try {
54	      $stream.Write($bytes, 0, $bytes.Length)
55	      $stream.Flush($true)
56	    } finally {
57	      $stream.Dispose()
58	    }
59	    if ($FailBeforePublish) {
60	      if ($env:WIRE_OR_CUT_DISPATCHER_TEST -ne '1') {
61	        throw 'WOC-D015 fault injection is test-only.'
62	      }
63	      throw 'WOC-D015 simulated pre-publish snapshot failure.'
64	    }
65	    if (Test-Path -LiteralPath $Path -PathType Leaf) {
66	      [IO.File]::Replace($tmp, $Path, $backup)
67	    } else {
68	      [IO.File]::Move($tmp, $Path)
69	    }
70	  } finally {
71	    if (Test-Path -LiteralPath $tmp -PathType Leaf) {
72	      Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
73	    }
74	    if (Test-Path -LiteralPath $backup -PathType Leaf) {
75	      Remove-Item -LiteralPath $backup -Force -ErrorAction SilentlyContinue
76	    }
77	  }
78	}
