80	function Invoke-WireCutDispatchGit {
81	  param(
82	    [Parameter(Mandatory)][string]$GitCommand,
83	    [Parameter(Mandatory)][string]$Workspace,
84	    [Parameter(Mandatory)][string[]]$Arguments
85	  )
86	  $prior = Get-Location
87	  $priorErrorAction = $ErrorActionPreference
88	  try {
89	    Set-Location -LiteralPath $Workspace
90	    $ErrorActionPreference = 'Continue'
91	    $output = @(& $GitCommand @Arguments 2>&1)
92	    $exitCode = $LASTEXITCODE
93	    [pscustomobject]@{
94	      ExitCode = if ($null -eq $exitCode) { 126 } else { [int]$exitCode }
95	      Output = ($output | Out-String).TrimEnd()
96	    }
97	  } catch {
98	    [pscustomobject]@{ ExitCode = 127; Output = $_.Exception.Message }
99	  } finally {
100	    $ErrorActionPreference = $priorErrorAction
101	    Set-Location -LiteralPath $prior
102	  }
103	}
