442	function Add-WireCutDispatchEventLine {
443	  param(
444	    [Parameter(Mandatory)][string]$EventsPath,
445	    [Parameter(Mandatory)]$Event
446	  )
447	  $dir = Split-Path -Parent $EventsPath
448	  if ($dir -and -not (Test-Path -LiteralPath $dir -PathType Container)) {
449	    New-Item -ItemType Directory -Path $dir -Force | Out-Null
450	  }
451	  $line = ($Event | ConvertTo-Json -Compress -Depth 20) + "`n"
452	  $bytes = [Text.UTF8Encoding]::new($false).GetBytes($line)
