472	function Write-WireCutDispatchStateMutation {
473	  param(
474	    [Parameter(Mandatory)][string]$SnapshotPath,
475	    [Parameter(Mandatory)][string]$EventsPath,
476	    [Parameter(Mandatory)]$SnapshotObject,
477	    [Parameter(Mandatory)][object[]]$EventObjects
478	  )
479	  if (@($EventObjects).Count -lt 1) {
480	    throw 'WOC-D006 state mutation requires at least one event.'
481	  }
482	  $nextSequence = [int]$SnapshotObject.last_transition_sequence
483	  $touchedSequences = @{}
484	  foreach ($event in @($EventObjects)) {
485	    $nextSequence++
486	    $event.sequence = $nextSequence
487	    $event.at = Get-WireCutUtcIsoNow
488	    if (Test-WireCutEventHasProperty -Event $event -Name 'effect_key') {
489	      $effectKey = [string](Get-WireCutEventProperty -Event $event -Name 'effect_key')
490	      if (Test-WireCutWorkPackageExists -WorkPackages $SnapshotObject.work_packages -EffectKey $effectKey) {
491	        $touchedSequences[$effectKey] = $nextSequence
492	      }
493	    }
494	    Add-WireCutDispatchEventLine -EventsPath $EventsPath -Event $event
495	  }
496	  foreach ($effectKey in $touchedSequences.Keys) {
497	    $pkg = Get-WireCutWorkPackageEntry -WorkPackages $SnapshotObject.work_packages -EffectKey $effectKey
498	    $pkg.last_transition_sequence = [int]$touchedSequences[$effectKey]
499	  }
500	  $SnapshotObject.last_transition_sequence = $nextSequence
501	  $SnapshotObject.work_packages = Sort-WireCutWorkPackages -Packages $SnapshotObject.work_packages
502	  Write-WireCutCanonicalJson -Path $SnapshotPath -Object $SnapshotObject
503	  return [pscustomobject]@{ sequence = $nextSequence }
504	}
