660	function Invoke-WireCutControlWorktreeHandoff {
661	  param(
662	    [Parameter(Mandatory)][string]$GitCommand,
663	    [Parameter(Mandatory)][string]$ControlWorktree
664	  )
665	  $status = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
666	    'status', '--porcelain=v1'
667	  )
668	  if ($status.ExitCode -ne 0 -or -not [string]::IsNullOrWhiteSpace($status.Output)) {
669	    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'Control worktree is dirty before handoff.' }
670	  }
671	  $fetch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
672	    'fetch', '--no-tags', 'origin', 'main', $script:WireCutDispatchStateBranch
673	  )
674	  if ($fetch.ExitCode -ne 0) {
675	    return [pscustomobject]@{ ok = $false; code = 'WOC-D002'; message = 'Control worktree fetch failed.' }
676	  }
677	  $stateRef = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
678	    'rev-parse', $script:WireCutDispatchStateRemoteRef
679	  )
680	  if ($stateRef.ExitCode -ne 0) {
681	    return [pscustomobject]@{ ok = $false; code = 'WOC-D014'; message = 'origin/wirecut-state is not resolvable for handoff.' }
682	  }
683	  $target = $stateRef.Output.Trim()
684	  $localStateBranch = Invoke-WireCutDispatchGit -GitCommand $GitCommand -Workspace $ControlWorktree -Arguments @(
685	    'show-ref', '--verify', '--quiet', "refs/heads/$($script:WireCutDispatchStateBranch)"
