=== features.ts: default states ===
/**
 * Feature-gate / config posture. (SPEC-15, SPEC-18, SPEC-23.2)
 *
 * Operator doctrine: **everything is built to full feature; config is the only
 * turn-off — never a traction/volume milestone.** Ecosystem participants
 * (pharmacy/diagnostics/insurer/pharma), data-product pipelines, and white-label
 * B2B2C are all BUILT, then shipped `dark_built`/`suspended` and flipped to
 * `active` by config. Each on-switch is a license / legal (PDPO) / certified-
 * partner / quality / infra gate — flipped reversibly, by config, not by code.
 *
 * The T1->T2->T3 accumulation plane and C0–C6 dependency order are NOT gated by
 * this (accumulation ships day one; build ORDER is sequenced, not deferred).
 * Only EXPOSURE/commercialization is gated here.
 */
import { z } from "zod";

/** Build/exposure state of a feature. Default for non-core features is `dark_built`. */
export const FeatureState = z.enum(["dark_built", "suspended", "active"]);
export type FeatureState = z.infer<typeof FeatureState>;

/** What flips a feature ON. Never "traction". */
export const OnSwitch = z.enum([
  "always", // core spine — no gate
  "license", // regulatory licence (e.g. pharmacy/lab)
  "legal_pdpo", // PDPO / legal clearance (data products, pharma signals)
  "certified_partner", // a certified connector partner is live
  "quality", // quality bar met
  "operating_layer_live", // B2B operating layer is live (white-label)
  "bd_pay_activation", // BD-Pay sponsor bank + licence + rails (C6)
]);
export type OnSwitch = z.infer<typeof OnSwitch>;

export const FeatureGate = z
  .object({
    key: z.string().min(1),
    state: FeatureState,
    on_switch: OnSwitch,
    note: z.string().default(""),
  })
  .strict();
export type FeatureGate = z.infer<typeof FeatureGate>;

/** A feature is EXPOSED to users only when active. dark_built/suspended => hidden. */
export function isExposed(gate: FeatureGate): boolean {
  return gate.state === "active";
}

/** Canonical AuraSphere feature keys. */
export const FEATURE_KEYS = [
  // Core spine (C0–C5, pay-at-clinic) — exposed.
  "directory_find",
  "booking",
  "records_erx",
  "advisory",
  "verification",
  "compliance_warranted",
  "telehealth",
  "payments_pay_at_clinic",
  // Built-to-full-feature, shipped dark_built/suspended — flipped by config.
  "payments_bd_pay_live", // C6 — bd_pay_activation
  "payments_aggregator_stopgap", // C6 — certified_partner (independent of BD-Pay rails)
  "pharmacy", // license + certified_partner
  "diagnostics_lab", // certified_partner
  "insurer", // license + legal
  "pharma_demand_signals", // legal_pdpo
  "white_label_b2b2c", // operating_layer_live
  "data_products", // legal_pdpo (SPEC-18)
  "practice_analytics", // quality — SPEC-19 internal provider/operator practice-intelligence federation read-port
] as const;
export type FeatureKey = (typeof FEATURE_KEYS)[number];

/**
 * The DEFAULT posture (overridable by config/features.json). Core = active;
 * everything else is built-and-dark, awaiting its non-traction on-switch.
 */
export const DEFAULT_FEATURE_POSTURE: Record<FeatureKey, FeatureGate> = {
  directory_find: { key: "directory_find", state: "active", on_switch: "always", note: "C0" },
  booking: { key: "booking", state: "active", on_switch: "always", note: "C3 pay-at-clinic" },
  records_erx: { key: "records_erx", state: "active", on_switch: "always", note: "C1" },
  advisory: { key: "advisory", state: "active", on_switch: "always", note: "C4 opt-in" },
  verification: { key: "verification", state: "active", on_switch: "always", note: "C2" },
  compliance_warranted: { key: "compliance_warranted", state: "active", on_switch: "always", note: "C5" },
  telehealth: { key: "telehealth", state: "active", on_switch: "always", note: "C3 self-host" },
  payments_pay_at_clinic: { key: "payments_pay_at_clinic", state: "active", on_switch: "always", note: "core" },
  payments_bd_pay_live: { key: "payments_bd_pay_live", state: "suspended", on_switch: "bd_pay_activation", note: "C6 — operator-gated" },
  payments_aggregator_stopgap: { key: "payments_aggregator_stopgap", state: "dark_built", on_switch: "certified_partner", note: "C6 — built full; independent aggregator (SSLCommerz/aamarPay) before BD-Pay rails" },
  pharmacy: { key: "pharmacy", state: "dark_built", on_switch: "license", note: "built; needs certified pharmacy partner + licence" },
  diagnostics_lab: { key: "diagnostics_lab", state: "dark_built", on_switch: "certified_partner", note: "built; needs certified lab partner" },
  insurer: { key: "insurer", state: "dark_built", on_switch: "license", note: "built; needs insurer partner + legal" },
  pharma_demand_signals: { key: "pharma_demand_signals", state: "dark_built", on_switch: "legal_pdpo", note: "built; PDPO clearance" },
  white_label_b2b2c: { key: "white_label_b2b2c", state: "dark_built", on_switch: "operating_layer_live", note: "built; B2B operating layer live" },
  data_products: { key: "data_products", state: "dark_built", on_switch: "legal_pdpo", note: "built; PDPO + provenance/fact-gate" },
  practice_analytics: { key: "practice_analytics", state: "dark_built", on_switch: "quality", note: "built; SPEC-19 PII-free provider/operator practice-intelligence federation read-port; flipped active by config when the analytics integrity/quality gate is satisfied" },
};

/** Config file schema (config/features.json). The runtime source of truth. */
export const FeatureConfig = z
  .object({
    version: z.number().int().nonnegative(),
    gates: z.array(FeatureGate),
  })
  .strict();
export type FeatureConfig = z.infer<typeof FeatureConfig>;

/**
 * Resolves whether a feature is exposed, from a (validated) config, fail-closed:
 * an unknown key, or a key absent from config, is NOT exposed. This is what
 * makes "config is the turn-off" real — flip the file, not the code.
 */
export class FeatureGateRegistry {
  private readonly gates: Map<string, FeatureGate>;

  constructor(config: FeatureConfig) {
    this.gates = new Map(config.gates.map((g) => [g.key, g]));
  }

  /** Build a registry from the validated default posture (used when no config file). */
  static fromDefault(): FeatureGateRegistry {
    return new FeatureGateRegistry({ version: 0, gates: Object.values(DEFAULT_FEATURE_POSTURE) });
  }

  gate(key: string): FeatureGate | undefined {
    return this.gates.get(key);
  }

  /** Fail-closed: unknown/absent => not exposed. */
  isExposed(key: string): boolean {
    const g = this.gates.get(key);
    return g !== undefined && isExposed(g);
  }

  state(key: string): FeatureState | "unknown" {
    return this.gates.get(key)?.state ?? "unknown";
  }
}

