  white_label_b2b2c: { key: "white_label_b2b2c", state: "dark_built", on_switch: "operating_layer_live", note: "built; B2B operating layer live" },
  data_products: { key: "data_products", state: "dark_built", on_switch: "legal_pdpo", note: "built; PDPO + provenance/fact-gate" },
  practice_analytics: { key: "practice_analytics", state: "dark_built", on_switch: "quality", note: "built; SPEC-19 PII-free provider/operator practice-intelligence federation read-port; flipped active by config when the analytics integrity/quality gate is satisfied" },
};

/** Config file schema (config/features.json). The runtime source of truth. */
export const FeatureConfig = z
  .object({
    version: z.number().int().nonnegative(),
    gates: z.array(FeatureGate),
  })
  .strict();
export type FeatureConfig = z.infer<typeof FeatureConfig>;

/**
 * Resolves whether a feature is exposed, from a (validated) config, fail-closed:
 * an unknown key, or a key absent from config, is NOT exposed. This is what
 * makes "config is the turn-off" real — flip the file, not the code.
 */
export class FeatureGateRegistry {
  private readonly gates: Map<string, FeatureGate>;

  constructor(config: FeatureConfig) {
    this.gates = new Map(config.gates.map((g) => [g.key, g]));
  }

  /** Build a registry from the validated default posture (used when no config file). */
  static fromDefault(): FeatureGateRegistry {
    return new FeatureGateRegistry({ version: 0, gates: Object.values(DEFAULT_FEATURE_POSTURE) });
  }

  gate(key: string): FeatureGate | undefined {
    return this.gates.get(key);
  }

  /** Fail-closed: unknown/absent => not exposed. */
  isExposed(key: string): boolean {
    const g = this.gates.get(key);
    return g !== undefined && isExposed(g);
  }

  state(key: string): FeatureState | "unknown" {
    return this.gates.get(key)?.state ?? "unknown";
  }
}

