# gitlab-sync-mirrors.ps1 — push GitHub origin/main to the GitLab mirror for each active proof-substrate repo.
# Registered as scheduled task 'GitLab-Mirror-Sync' (every 30 min) on 2026-07-17 after the mirrors were
# found frozen 4-9 days (no sync automation existed; red CI banners were stale-code artifacts).
# bd-pay is DELIBERATELY excluded: its GitLab is frozen per the 2026-06-25 ruling (GitHub is authoritative).
# Fail-open per repo (one repo's failure must not block the others); every outcome logged.

$ErrorActionPreference = 'Continue'
$logDir = 'C:\Users\saadm\.claude\logs'
if (-not (Test-Path $logDir)) { New-Item -ItemType Directory -Path $logDir -Force | Out-Null }
$log = Join-Path $logDir 'gitlab-sync.log'
$lines = @("=== gitlab-sync $(Get-Date -Format o) ===")

$repos = @(
  @{ path = 'C:\Users\saadm\Projects\portfolio-core';   gitlab = 'https://gitlab.com/ss-group3592724/portfolio-core.git' },
  @{ path = 'C:\Users\saadm\Projects\operatorbench';    gitlab = 'https://gitlab.com/ss-group3592724/operatorbench.git' },
  @{ path = 'C:\Users\saadm\Projects\management-company'; gitlab = 'https://gitlab.com/ss-group3592724/management-company.git' }
)

foreach ($r in $repos) {
  $name = Split-Path $r.path -Leaf
  if (-not (Test-Path (Join-Path $r.path '.git'))) { $lines += "$name SKIP repo-missing"; continue }
  & git -C $r.path fetch origin --quiet 2>&1 | Out-Null
  if ($LASTEXITCODE -ne 0) { $lines += "$name FAIL fetch (exit $LASTEXITCODE)"; continue }
  $localSha  = (& git -C $r.path rev-parse origin/main 2>$null)
  $remoteSha = (& git -C $r.path ls-remote $r.gitlab refs/heads/main 2>$null | ForEach-Object { ($_ -split "`t")[0] }) | Select-Object -First 1
  if ($localSha -and $remoteSha -eq $localSha) { $lines += "$name OK already-current $($localSha.Substring(0,8))"; continue }
  $out = & git -C $r.path push $r.gitlab origin/main:main 2>&1
  if ($LASTEXITCODE -eq 0) { $lines += "$name OK pushed $($localSha.Substring(0,8))" }
  else { $lines += "$name FAIL push (exit $LASTEXITCODE): $(($out | Select-Object -Last 1))" }
}

$lines | Set-Content -LiteralPath $log -Encoding utf8
exit 0

