// GitLab API helper. Usage: node gl.js <urlencoded-project> <api-path>
// Prints jobs compactly, or raw JSON (truncated) for objects.
const https = require("https");
const [proj, apipath] = process.argv.slice(2);
const tok = process.env.GITLAB_READ_PAT;
const url = `https://gitlab.com/api/v4/projects/${proj}${apipath}`;
https.get(url, { headers: { "PRIVATE-TOKEN": tok } }, (r) => {
  let s = "";
  r.on("data", (d) => (s += d));
  r.on("end", () => {
    try {
      const j = JSON.parse(s);
      if (Array.isArray(j)) {
        for (const x of j) {
          if (x.name && x.status) {
            let line = "  " + x.stage + "/" + x.name + " -> " + x.status;
            if (x.status === "failed") line += "  [" + (x.failure_reason || "?") + "]";
            console.log(line);
          } else if (x.id && x.status && x.sha) {
            console.log("  pipeline " + x.id + " " + x.status + " sha=" + String(x.sha).slice(0, 8) + " src=" + x.source + " " + x.created_at);
          } else {
            console.log("  " + JSON.stringify(x).slice(0, 160));
          }
        }
      } else {
        console.log(JSON.stringify(j).slice(0, 400));
      }
    } catch (e) {
      console.log("PARSE-ERR: " + s.slice(0, 160));
    }
  });
}).on("error", (e) => console.log("HTTP-ERR: " + e.message));

