-- Migration 0030: worker autopilot settings
-- Stores per-worker configuration for the autopilot auto-claim feature.
-- score_threshold is stored as an integer 0-100 (basis points * 100).

create table if not exists worker_autopilot (
  worker_id            uuid not null references profiles(id) on delete cascade,
  enabled              boolean not null default false,
  score_threshold      integer not null default 75 check (score_threshold >= 0 and score_threshold <= 100),
  max_concurrent_tasks integer not null default 3 check (max_concurrent_tasks >= 1),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  primary key (worker_id)
);

alter table worker_autopilot enable row level security;

-- Worker can read and write their own autopilot row only.
create policy autopilot_self_rw on worker_autopilot
  for all
  using (
    worker_id in (
      select id from profiles where user_id = auth.uid()
    )
  )
  with check (
    worker_id in (
      select id from profiles where user_id = auth.uid()
    )
  );

