// Idempotent-aware migration apply for khep's drifted prod DB.
// - Applies genuinely-new migrations transactionally.
// - On an "already exists" error (object pre-applied out-of-band), records the migration
//   as applied and continues — logging it for audit.
// - HALTS on any other error (real problem). Run from the khep repo root.
import fs from "fs";
import path from "path";
import pg from "pg";

const dir = "backend/supabase/migrations";
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const ALREADY_EXISTS = new Set(["42710", "42P07", "42P06", "42701", "42723", "42P16"]); // policy/table/schema/column/object/rule dup

const c = new pg.Client({ connectionString: process.env.DATABASE_URL });
await c.connect();
await c.query("create table if not exists _migrations(name text primary key, applied_at timestamptz not null default now())");

let applied = 0, reconciled = 0;
for (const f of files) {
  const done = (await c.query("select 1 from _migrations where name=$1", [f])).rowCount;
  if (done) continue;
  const sql = fs.readFileSync(path.join(dir, f), "utf8");
  await c.query("begin");
  try {
    await c.query(sql);
    await c.query("insert into _migrations(name) values($1)", [f]);
    await c.query("commit");
    applied++;
    console.log("APPLIED    " + f);
  } catch (e) {
    await c.query("rollback");
    if (ALREADY_EXISTS.has(e.code)) {
      await c.query("insert into _migrations(name) values($1) on conflict do nothing", [f]);
      reconciled++;
      console.log("RECONCILED " + f + "  (pre-existing " + e.code + ": " + String(e.message).slice(0, 70) + ")");
    } else {
      console.log("HALT at " + f + ": " + e.code + " " + String(e.message).slice(0, 140));
      await c.end();
      process.exit(3);
    }
  }
}
console.log(`DONE — applied ${applied}, reconciled ${reconciled}.`);
await c.end();

